window.ROUTE_LUCHEN = {"id":"luchen","name":"陆沉","floor":22,"flag1Week":26,"flag2Week":39,"flag1Need":60,"flag2Need":80,"flag1Label":"旧笔记","flag2Label":"地图","tagline":"「两个不肯认输的人，最后谁先低头？」","chapters":[{"id":"extra","title":"番外 · 名字被涂掉的那一页","scenes":[{"no":1,"title":"第四排靠窗","week":0,"bg":"classroom","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"初一的座位按身高排。全班在走廊里站成一列，老师从头念名字。"},{"t":"n","text":"念到你，她抬手指了指第四排靠窗：「那儿。」"},{"t":"n","text":"你走过去，路过第三排的时候，看见有人在写名字。"},{"t":"n","text":"他把课本包了牛皮纸书皮，四个角折得一样齐。写完，他把笔放下。笔是铅笔，用到只剩半截。"},{"t":"n","text":"你坐下，桌子晃了一下，桌脚短了一截。"},{"t":"n","text":"后面那个人开口了。"},{"t":"c","id":"luchen","text":"你桌子晃。"},{"t":"n","text":"他没抬头，从笔袋里抽出一张折过两次的纸，推到你椅子下面。"},{"t":"n","text":"你回头。他已经低头了。你看见他的后颈，头发剪得很短，发际线那里有一道浅浅的推子印。"},{"t":"n","text":"你把纸垫在桌脚下。桌子不晃了。"},{"t":"n","text":"第一节课，老师让自我介绍。轮到第三排，他站起来，说了两个字。"},{"t":"c","id":"luchen","text":"陆沉。"},{"t":"n","text":"老师等了两秒：「就这些？」"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"他坐下。全班笑了一下，很短，很快散了。他没有笑，也没有不高兴。"},{"t":"n","text":"数学课，老师讲一元一次方程，讲到第二道例题，问有没有人愿意上黑板做。"},{"t":"n","text":"没有人举手。老师看了看名单，念了他。"},{"t":"n","text":"他上去，拿粉笔的时候先在手心里把粉笔头掰掉一小截。他写得很快，写完就下来了，没有等老师评价。"},{"t":"n","text":"老师看了半分钟，说：「对。这个写法比我讲的快。」"},{"t":"n","text":"他回座位的时候，你看见他耳朵有一点红。只红了一下。"},{"t":"n","text":"下课，教室里乱起来。他从书包里拿出一个本子，摊开，开始做下一节的题。"},{"t":"n","text":"你回头看黑板，想把他刚才的写法抄下来。"},{"t":"n","text":"粉笔字已经被人擦了。"},{"t":"n","text":"你转回去，发现桌上多了一张纸。上面是那道题的步骤，一步一步，字很小，很用力，纸背有印。"},{"t":"n","text":"你回头。他还在做题。"},{"t":"n","text":"你没有说谢谢。你也不知道该不该说。"},{"t":"n","text":"放学的时候，教室里只剩你们两个。你收书包，他还在写。"},{"t":"n","text":"你走到门口，听见后面响了一声。你回头。"},{"t":"n","text":"他弯腰，把你那把椅子推回了桌子底下。"},{"t":"n","text":"他看见你在看，直起身，说了一句不相干的。"},{"t":"c","id":"luchen","text":"明天早上七点二十开门。"},{"t":"n","text":"你「哦」了一声。"},{"t":"n","text":"后来你才知道，那句话的意思是：他想让你早点来，坐那个位置。"},{"t":"n","text":"他自己大概也不知道这句话是那个意思。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"第二天七点十分到教室","hint":"早一点 · 把位置占住","eff":{"aff":4.0,"int":2.0,"stress":1.0},"reply":[{"t":"n","text":"教室门还锁着。走廊里只有一个拖把桶，水是隔夜的。"},{"t":"n","text":"七点十八，楼梯口传来脚步声。他上来，看见你，脚步慢了半拍。"},{"t":"c","id":"luchen","text":"门没开。"},{"t":"n","text":"你说你知道。"},{"t":"n","text":"他把书包放在地上，从里面拿出一本书，也放在地上，然后靠着墙坐下来。"},{"t":"n","text":"离上课还有四十分钟。你们一句话也没说。"},{"t":"n","text":"七点二十，管理员来开门。他先进去，走到第三排，把书包放下，然后回头看你。"},{"t":"n","text":"他把旁边那把椅子拉出来了一点。"}]},{"label":"B","text":"跟他说一声谢谢","hint":"把话说完 · 心里舒服一点","eff":{"aff":2.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你走回去，说：「那张纸，谢谢。」"},{"t":"n","text":"他抬起头，好像没听懂。"},{"t":"c","id":"luchen","text":"哪张。"},{"t":"n","text":"你指了指黑板的方向。他「哦」了一声。"},{"t":"c","id":"luchen","text":"那个不用谢。"},{"t":"n","text":"他把本子合上，塞进书包，动作很快。"},{"t":"n","text":"走到楼梯口，他忽然停下来，没回头。"},{"t":"c","id":"luchen","text":"以后我写的东西，你别抄。抄了没用。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他往下走了两级，又补了一句。"},{"t":"c","id":"luchen","text":"可以问我。"}]},{"label":"C","text":"什么也没说，先回家","hint":"不打破这个安静 · 松一点","eff":{"aff":1.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你走出教学楼，天还没黑。操场上有人在跑步，一圈一圈。"},{"t":"n","text":"你回头看了一眼四楼的窗。灯还亮着。"},{"t":"n","text":"第二天早上，你到教室时，桌上放着那张纸，被人用透明胶贴在桌角，压得平平整整。"},{"t":"n","text":"纸上多了一行小字，写在最下面：「别对着答案做。」"},{"t":"n","text":"你抬头。他在看书，没有看你。"},{"t":"n","text":"那张纸在桌上贴了一整个学期。换教室的时候，你把它撕下来，撕坏了一角。"}]}]},{"t":"n","text":"九月的最后一周，班里排了一次周测。成绩出来那天，你从他旁边过，看见他的卷子摊在桌上。"},{"t":"n","text":"满分。他在卷子背面继续写题，像那张卷子跟他没关系。"},{"t":"n","text":"你回到座位，翻开自己的卷子。错的那道题，他昨天刚讲过。"}],"id":"luchen_01"},{"no":2,"title":"榜前的那两分钟","week":0,"bg":"corridor_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"期中成绩贴在教学楼中庭。红纸，黑字，从第一名排到第一百名。"},{"t":"n","text":"人很多。你从人缝里挤进去，先看第一行。"},{"t":"n","text":"陆沉。年级第一。数学满分，语文八十九。"},{"t":"n","text":"你往下找自己。第七。"},{"t":"n","text":"你退出来，看见他站在人群外面，没有挤。"},{"t":"n","text":"他站的位置，正对着红纸的左上角。隔着十几个人的后脑勺。"},{"t":"n","text":"他看了大概两分钟。然后走了。"},{"t":"n","text":"下午最后一节是自习。有个老师在门口敲了两下门框。"},{"t":"n","text":"「陆沉，出来一下。」"},{"t":"n","text":"你抬头。那个老师四十多岁，头发往一边梳，衬衫领口的扣子系到最上面。"},{"t":"n","text":"两个人站在走廊上。门没关严，声音漏进来一点。"},{"t":"n","text":"「这次数学不难。」"},{"t":"n","text":"他说：「嗯。」"},{"t":"n","text":"「年级第一，别骄傲。」"},{"t":"n","text":"「嗯。」"},{"t":"n","text":"「你妈那边，你自己说。」"},{"t":"n","text":"走廊上安静了几秒。"},{"t":"n","text":"「语文八十九。」那个老师说，「八十九是什么概念，你心里清楚。」"},{"t":"n","text":"「清楚。」"},{"t":"n","text":"「行。回去吧。」"},{"t":"n","text":"他回来坐下，把笔袋打开，又合上，又打开。"},{"t":"n","text":"那节课他一道题也没做。他一直在写同一个字，写完就划掉，写完就划掉。"},{"t":"n","text":"下课你去倒水，路过往他桌上瞥了一眼。那张草稿纸上全是「陆」字。"},{"t":"n","text":"最后一排的位置，最后一笔都拖得很长。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把自己那张卷子递过去","hint":"看看别人的错 · 换个话题","eff":{"aff":4.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你把语文卷子放在他桌上，指着作文那一栏：「你帮我看看，这儿为什么扣了八分。」"},{"t":"n","text":"他看了三秒。"},{"t":"c","id":"luchen","text":"你写了三个比喻，都指向同一个东西。老师不知道你想说什么。"},{"t":"n","text":"你说：「我想说的就是这个啊。」"},{"t":"n","text":"他把卷子推回来。"},{"t":"c","id":"luchen","text":"那就写清楚。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"我也不会写。"},{"t":"n","text":"这是他第一次说这三个字。他说得很轻，像怕被人听见。"}]},{"label":"B","text":"什么也不问，帮他把窗户关上","hint":"不多话 · 让风小一点","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"起风了。走廊那头的窗户没关，纸被吹得响。"},{"t":"n","text":"你过去把窗户关上，把插销插好。"},{"t":"n","text":"回来的时候，他的草稿纸被吹到了地上。你捡起来，放在他桌角。"},{"t":"n","text":"他抬头看你，看了两秒。"},{"t":"c","id":"luchen","text":"谢谢。"},{"t":"n","text":"那天晚自习，他做题的速度比平时慢。你听见他翻页的声音，一页，一页，很整齐。"}]},{"label":"C","text":"问他，那个人是谁","hint":"问一句 · 会碰到硬的东西","eff":{"aff":1.0,"eq":1.0,"stress":2.0},"reply":[{"t":"n","text":"你问：「刚才那个老师，是你爸？」"},{"t":"n","text":"他把笔帽扣上。扣了两次才扣进去。"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"你说：「他也教我们学校？」"},{"t":"c","id":"luchen","text":"教高三物理。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"luchen","text":"他教过的学生，有三个考上过一个地方。"},{"t":"n","text":"他没说是哪个地方。"},{"t":"n","text":"你也没有问。"},{"t":"n","text":"从那天起，你再看见办公室门口那个系紧领口的男人，就会想起那张红纸。"}]}]},{"t":"n","text":"晚上回家，你把成绩单放在饭桌上。你妈看了，说：「第七，还行。」"},{"t":"n","text":"你爸把成绩单翻过来，看了看背面有没有字。"},{"t":"n","text":"你说：「我们年级第一，是他爸教出来的。」"},{"t":"n","text":"你妈没听懂。她给你夹了一筷子菜，说：「那你多跟人家学学。」"},{"t":"n","text":"你说好。"},{"t":"n","text":"你不知道该学什么。你只知道，他今天在走廊上站的那两分钟，比一整个晚自习都长。"},{"t":"n","text":"第二天早自习，他把一张纸推到你桌上。"},{"t":"n","text":"纸上抄着年级前二十的名字，每个名字后面标了分数。第七名那一行，被人用铅笔画了一道线。"},{"t":"n","text":"你说：「你抄这个干嘛。」"},{"t":"n","text":"他把纸抽回去，折好。"},{"t":"c","id":"luchen","text":"看差距。"},{"t":"n","text":"你问：「差多少。」"},{"t":"n","text":"他算了一下，报了一个数。那个数不大。"},{"t":"c","id":"luchen","text":"一个学期的距离。"},{"t":"n","text":"他说完，把纸塞进课本里，压平。"},{"t":"n","text":"那道铅笔画过的线，从那天起每天都换一个位置。往上，一格一格。"}],"id":"luchen_02"},{"no":3,"title":"家属楼三单元","week":0,"bg":"livingroom_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"三月，学校旁边的梧桐开始掉毛。班里流行感冒，他请了三天假。"},{"t":"n","text":"老师让把这三天的卷子送过去。名单上第一个名字是你，因为你们住得近。"},{"t":"n","text":"家属楼在学校后门，三单元，四楼。楼道里有煤气味和炒菜声。"},{"t":"n","text":"你敲门。开门的是他。"},{"t":"n","text":"他穿着家里的旧T恤，头发没有梳。看见你，他愣了一下。"},{"t":"c","id":"luchen","text":"你怎么来了。"},{"t":"n","text":"你说送卷子。他接过，往旁边让了让。"},{"t":"c","id":"luchen","text":"进来。"},{"t":"n","text":"屋子不大，很干净。客厅的墙刷成白色，一面墙上贴满了纸。"},{"t":"n","text":"都是复印件。录取通知书的复印件，一张一张，用透明胶贴在墙上，边角对得很齐。"},{"t":"n","text":"最上面一张是最旧的，纸已经黄了，上面写着「北京某大学 物理系」。"},{"t":"n","text":"你数了一下，一共七张。"},{"t":"n","text":"他端着水从厨房出来，看见你在看那面墙。"},{"t":"n","text":"他把水放在桌上，没有解释。"},{"t":"c","id":"luchen","text":"卷子放那儿吧。"},{"t":"n","text":"桌上摊着一本书。不是课本，硬壳，深蓝，书脊用透明胶粘过。"},{"t":"n","text":"你多看了一眼。他顺着你的目光看过去，停了一下。"},{"t":"c","id":"luchen","text":"这本不是我的。"},{"t":"n","text":"你说：「那是谁的？」"},{"t":"n","text":"他没有马上回答。他把书翻开，翻到扉页。"},{"t":"n","text":"扉页上有一个名字，钢笔写的，被涂掉了。涂得很用力，纸都起毛了。"},{"t":"n","text":"涂掉的名字上面，写着「陆沉」两个字。字很小，很用力。"},{"t":"n","text":"「我爸的。」他说，「他当年考大学用的。」"},{"t":"n","text":"你问：「那原来那个名字是谁？」"},{"t":"c","id":"luchen","text":"他学生。"},{"t":"n","text":"他把书合上。"},{"t":"c","id":"luchen","text":"考上那个地方，后来没去成。"},{"t":"n","text":"「为什么？」"},{"t":"n","text":"他说：「家里没钱。」"},{"t":"n","text":"厨房里传来声音：「陆沉，让同学留下吃饭。」"},{"t":"n","text":"他看了你一眼。那一眼的意思你后来才读懂：他希望你说好。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"留下来吃饭","hint":"坐下来 · 会看见更多","eff":{"aff":6.0,"happy":3.0,"stress":1.0},"reply":[{"t":"n","text":"饭桌很小，四个人坐得满。三菜一汤，汤是紫菜蛋花。"},{"t":"n","text":"他父亲坐在主位，衬衫换了，领口还是系着。"},{"t":"n","text":"「你这次第七。」他父亲忽然说。"},{"t":"n","text":"你愣了一下。他说：「我看过成绩单。」"},{"t":"n","text":"「第七不错。」他父亲夹了一筷子菜，「第七还有往上走的空间。」"},{"t":"n","text":"你说了声谢谢。"},{"t":"n","text":"「陆沉这次第三。」他父亲说，「退了两名。」"},{"t":"n","text":"桌上安静了一下。他母亲说：「吃饭。」"},{"t":"n","text":"陆沉低头喝汤，喝完把碗放下。"},{"t":"c","id":"luchen","text":"下次考回来。"},{"t":"n","text":"他父亲点点头，像在验收一个工程。"},{"t":"n","text":"那顿饭你吃得很快。走的时候，他送你到楼道口。"},{"t":"n","text":"灯是声控的，一亮一灭。他站在明暗交界的地方。"},{"t":"c","id":"luchen","text":"你别学我。"},{"t":"n","text":"你问：「学你什么？」"},{"t":"n","text":"他没有答。"}]},{"label":"B","text":"说家里等着，改天再来","hint":"保持距离 · 也留了门","eff":{"aff":2.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你说你妈等着，得回去。"},{"t":"n","text":"他点点头，说「嗯」。"},{"t":"n","text":"你把卷子放下，走到门口。他忽然叫住你。"},{"t":"c","id":"luchen","text":"等一下。"},{"t":"n","text":"他回房间，出来时手里拿着那本深蓝的旧笔记。"},{"t":"c","id":"luchen","text":"这三天的题，你抄一下。抄完还我。"},{"t":"n","text":"你说好。你接过的时候，摸到书脊上的透明胶，有点硌手。"},{"t":"n","text":"走到二楼，你听见楼上开门的声音。很轻，然后又关上。"}]},{"label":"C","text":"问他，那七张纸都是他爸的学生吗","hint":"把话问到底 · 有点冒险","eff":{"aff":4.0,"eq":2.0,"stress":2.0},"reply":[{"t":"n","text":"你问：「这些，都是你爸教出来的？」"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"「他们现在呢？」"},{"t":"n","text":"他把水杯推到你面前。"},{"t":"c","id":"luchen","text":"有一个在国外。有一个在研究所。有一个……"},{"t":"n","text":"他停住了。"},{"t":"n","text":"「有一个怎么了？」"},{"t":"c","id":"luchen","text":"有一个回来当了老师。教初中。"},{"t":"n","text":"他说完，抬眼看你。"},{"t":"c","id":"luchen","text":"我爸说，那个最可惜。"},{"t":"n","text":"你看着那面墙。七张纸，一张比一张新。"},{"t":"n","text":"最下面那张的右下角，用铅笔写了一个日期。是今年的。"}]}]},{"t":"n","text":"你下楼的时候，天已经黑了。家属楼的窗户一格一格亮着。"},{"t":"n","text":"四楼那扇窗也亮着。你看见一个人影在窗前站了一会儿，把窗帘拉上了。"},{"t":"n","text":"回家路上，你想的是那本笔记的扉页。"},{"t":"n","text":"一个名字被涂掉，写上下一个。像换一块牌子。"},{"t":"n","text":"你不知道自己为什么记得这么清楚。"}],"id":"luchen_03"},{"no":4,"title":"最后一题","week":0,"bg":"sakura_path","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"中考第二天，最后一科数学。"},{"t":"n","text":"考场在三楼，风扇在头顶转，转一圈，试卷的角翘一下。"},{"t":"n","text":"前面的题都不难。你做到倒数第二页，还剩四十分钟。"},{"t":"n","text":"最后一题，十二分。两个小问。"},{"t":"n","text":"第一问你做了。第二问，你写到一半，卡住了。"},{"t":"n","text":"你在草稿纸上画了一条辅助线，觉得不对，划掉。又画了一条。"},{"t":"n","text":"监考老师从你旁边走过去，鞋底在地板上响。"},{"t":"n","text":"你忽然想起那本深蓝笔记里的一页。那一页的角上，有一个画了一半的图，被人用铅笔轻轻描过一遍。"},{"t":"n","text":"你按那个图，重新画了一遍。"},{"t":"n","text":"做出来了。"},{"t":"n","text":"铃响的时候，你的手心全是汗，笔差点从手里滑下去。"},{"t":"n","text":"出考场，走廊里全是人。有人在哭，有人在对着答案大喊。"},{"t":"n","text":"你在楼梯口看见他。"},{"t":"n","text":"他站在台阶上，手里拿着笔袋，脸上没什么表情。"},{"t":"n","text":"你走过去。他先开口。"},{"t":"c","id":"luchen","text":"最后一题。"},{"t":"n","text":"你说：「做出来了。」"},{"t":"n","text":"他看了你两秒。"},{"t":"c","id":"luchen","text":"第二问？"},{"t":"n","text":"你点头。"},{"t":"n","text":"他把视线移开，看向操场。"},{"t":"c","id":"luchen","text":"我没做出来。"},{"t":"n","text":"他说得很平，像在说别人的事。"},{"t":"n","text":"你不知道该说什么。你说了句「可能是我想多了」，说完就后悔。"},{"t":"n","text":"他没有接话。他把笔袋塞进口袋，往楼下走。"},{"t":"n","text":"走了三级台阶，他停下来。"},{"t":"c","id":"luchen","text":"你怎么做的。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把辅助线画给他看","hint":"蹲下来 · 在台阶上讲题","eff":{"aff":6.0,"int":2.0,"happy":2.0},"reply":[{"t":"n","text":"你从书包里翻出一张草稿纸，蹲在台阶上画。"},{"t":"n","text":"他也蹲下来。两个人在楼梯中间，挡住了后面的人。"},{"t":"n","text":"有人从你们旁边挤过去，说了一句「让让」。"},{"t":"n","text":"你画完，抬头。他盯着那张纸，看了很久。"},{"t":"c","id":"luchen","text":"这一步，怎么想到的。"},{"t":"n","text":"你说：「笔记上有。你爸那本。」"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"哪一页。"},{"t":"n","text":"你翻了半天，翻到那一页。角上有一个画了一半的图。"},{"t":"n","text":"他看了很久，久到楼梯上的人都走完了。"},{"t":"c","id":"luchen","text":"这页我看了三年。"},{"t":"n","text":"他把纸拿过去，折好，放进笔袋。"},{"t":"c","id":"luchen","text":"谢谢。"},{"t":"n","text":"这是你第一次听他说这两个字，说得比上一次清楚。"}]},{"label":"B","text":"说「不重要了，都考完了」","hint":"把这件事放下 · 也别提","eff":{"aff":2.0,"happy":1.0,"stress":-2.0},"reply":[{"t":"n","text":"你说：「不重要了，都考完了。」"},{"t":"n","text":"他「嗯」了一声。"},{"t":"n","text":"你们一起下楼。操场上的梧桐被剪过，光秃秃的。"},{"t":"n","text":"走到校门口，他忽然说：「你刚才想了多久。」"},{"t":"n","text":"你说：「没多久。」"},{"t":"n","text":"他点点头。"},{"t":"c","id":"luchen","text":"行。"},{"t":"n","text":"那天他没有再提。但一个月后，你去他家还书，看见那本旧笔记摊在桌上。"},{"t":"n","text":"翻到的那一页，正是最后一题的那一页。旁边多了一行铅笔字：「辅助线从右上角走。」"}]},{"label":"C","text":"反问他：「你为什么没做出来」","hint":"问他的失误 · 会碰到他","eff":{"aff":3.0,"eq":2.0,"stress":1.0},"reply":[{"t":"n","text":"你问：「你怎么会没做出来。」"},{"t":"n","text":"他低下头，看着自己的鞋。"},{"t":"c","id":"luchen","text":"我用了另一种方法。算了二十分钟，算不出来。"},{"t":"n","text":"「为什么不换？」"},{"t":"c","id":"luchen","text":"因为前面都对了。"},{"t":"n","text":"他说完，自己笑了一下。那个笑很短，像一次呼吸。"},{"t":"c","id":"luchen","text":"我爸说，做不出来就换。可我不信。"},{"t":"n","text":"你看着他。他站在台阶上，比你高半级。"},{"t":"n","text":"他补了一句：「现在信了。」"}]}]},{"t":"n","text":"出校门的时候，天还亮着。门口有家长举着牌子，牌子上的字被太阳晒得发白。"},{"t":"n","text":"你回头找他的影子。他混在人群里，头发很短，背挺得很直。"},{"t":"n","text":"你正要走，有人从后面叫你的名字。"},{"t":"n","text":"他走过来，把那本深蓝的旧笔记递给你。"},{"t":"c","id":"luchen","text":"暑假看完。开学还我。"},{"t":"n","text":"你说：「你自己不用？」"},{"t":"n","text":"他把手插回口袋。"},{"t":"c","id":"luchen","text":"我用不着了。"},{"t":"n","text":"你翻开扉页。那个被涂掉的名字上面，「陆沉」两个字写得又小又用力。"},{"t":"n","text":"他说：「你别在上面写名字。」"},{"t":"n","text":"你问为什么。"},{"t":"n","text":"他已经转身走了。"},{"t":"n","text":"走了几步，他抬起左手看了一眼表。动作很快。"},{"t":"n","text":"你看见那块表。深蓝尼龙表带，表盘上有一道划痕。"},{"t":"n","text":"那天下午，你在校门口站了很久。手里的书有一点沉。"},{"t":"n","text":"暑假里，你把那本笔记从头看到尾。每一页都有两种笔迹：一种是钢笔，一种是铅笔。"},{"t":"n","text":"钢笔的笔迹很老，铅笔的很新。"},{"t":"n","text":"你翻到最后一页，看见一行小字，写在页脚："},{"t":"n","text":"「第二名也可以。」"},{"t":"n","text":"字是铅笔写的，写得很轻，几乎看不清。"}],"id":"luchen_04"}]},{"id":"ch1","title":"第一章 · 高中","scenes":[{"no":5,"title":"又坐前后桌","week":1,"bg":"classroom","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"高一（三）班的名单贴在教室门上。你在一列名字里找自己，找到一半，看见了他。"},{"t":"n","text":"陆沉。第三行。"},{"t":"n","text":"你进门。教室刚粉刷过，有一股石灰味。座位没排，先到先坐。"},{"t":"n","text":"第三排靠窗的位置空着。桌上放着两本书，摊得很正。"},{"t":"n","text":"你把书包放下，才发现旁边的椅子被人拉开了一点。"},{"t":"n","text":"门口有人进来。是他。"},{"t":"n","text":"他比初中高了半个头，头发还是那个长度，白衬衫，领口解开一颗扣。"},{"t":"n","text":"他看见你，脚步没停，走到桌边，把书往自己那边挪了两本。"},{"t":"c","id":"luchen","text":"你坐。"},{"t":"n","text":"你说：「我坐了别人的位置？」"},{"t":"n","text":"他把椅子往里推了一下。"},{"t":"c","id":"luchen","text":"我的。两张。"},{"t":"n","text":"你愣了一下。他已经坐下了，把笔袋打开，摆在桌角。"},{"t":"n","text":"开学第一节课，班主任让每个人说一句暑假做了什么。"},{"t":"n","text":"轮到他，他站起来。"},{"t":"c","id":"luchen","text":"看书。"},{"t":"n","text":"班主任笑着问：「看了什么书？」"},{"t":"c","id":"luchen","text":"课本。"},{"t":"n","text":"全班笑。他没有笑。"},{"t":"n","text":"下课，班主任在走廊上叫住你，问你初中是不是跟他一个班。"},{"t":"n","text":"你说一个班。"},{"t":"n","text":"老师点点头：「那好。他这个人，不太跟人说话。你多带带他。」"},{"t":"n","text":"你回头看教室。他一个人坐在窗边，正在写什么。"},{"t":"n","text":"阳光从窗户进来，落在他的手上。那只旧手表在光里，表盘上的划痕看得很清楚。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"坐过去，把初中的笔记还他","hint":"把东西还了 · 也算打招呼","eff":{"aff":5.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你把那本深蓝的旧笔记放在他桌上。"},{"t":"n","text":"他抬起头，看了两秒才认出来。"},{"t":"c","id":"luchen","text":"你还留着。"},{"t":"n","text":"你说：「说好开学还的。」"},{"t":"n","text":"他把书拿过去，翻开扉页。那个被涂掉的名字还在。"},{"t":"n","text":"他看了一会儿，把书合上，放进书包最里层。"},{"t":"c","id":"luchen","text":"看完了？"},{"t":"n","text":"你说看完了。"},{"t":"n","text":"他点点头。"},{"t":"c","id":"luchen","text":"最后一页那行字，你看见了吗。"},{"t":"n","text":"你说看见了。"},{"t":"n","text":"他没有再说话。他低头继续写，写了三行，忽然停下。"},{"t":"c","id":"luchen","text":"那不是我写的。"}]},{"label":"B","text":"问他暑假去了哪儿","hint":"先聊聊 · 别急着说正事","eff":{"aff":3.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你问：「暑假去哪儿了？」"},{"t":"n","text":"他把笔帽扣上。"},{"t":"c","id":"luchen","text":"学校。"},{"t":"n","text":"「哪个学校？」"},{"t":"c","id":"luchen","text":"我爸的学校。他给我排了课表。"},{"t":"n","text":"你说：「一天几节？」"},{"t":"c","id":"luchen","text":"六节。晚上两节自习。"},{"t":"n","text":"他说得很平。你算了一下，那不是暑假。"},{"t":"n","text":"「有休息吗？」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"luchen","text":"星期天下午。"},{"t":"n","text":"「你干什么？」"},{"t":"c","id":"luchen","text":"洗衣服。"},{"t":"n","text":"他说完，自己也觉得有点好笑，嘴角动了一下，很快收回去。"}]},{"label":"C","text":"先不打扰，回自己座位","hint":"先各做各的 · 也自然","eff":{"aff":1.0,"happy":1.0,"stress":-1.0},"reply":[{"t":"n","text":"你回到自己的位置，把课本摞起来。"},{"t":"n","text":"中午吃饭，你回来得早，教室里只有他一个。"},{"t":"n","text":"他桌上摊着一本练习册，旁边的椅子还是被拉开的状态。"},{"t":"n","text":"你走过去坐下，他头也没抬。"},{"t":"c","id":"luchen","text":"你早上为什么不过来。"},{"t":"n","text":"你说：「看你在忙。」"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"luchen","text":"我不忙。"},{"t":"n","text":"他补了一句：「我一直在等你说句话。」"}]}]},{"t":"n","text":"九月过完，班里重新排了一次座位。按成绩。"},{"t":"n","text":"他第一。你第四。座位表上，你们还在同一排，中间隔了一个人。"},{"t":"n","text":"搬桌子那天，他把自己的桌子推到窗边，又把你的桌子往他那边挪了半尺。"},{"t":"n","text":"负责登记的同学说：「哎，位置是按表来的。」"},{"t":"n","text":"他头也没抬。"},{"t":"c","id":"luchen","text":"表上没写不能挪半尺。"},{"t":"n","text":"那个人看了看表，没再说什么。"},{"t":"n","text":"中午吃饭，你端着餐盘找位置。他已经坐在靠窗那张桌子，对面放着一个空盘。"},{"t":"n","text":"你走过去。他把那个空盘往自己那边挪了挪。"},{"t":"c","id":"luchen","text":"坐。"},{"t":"n","text":"你坐下。他吃饭很快，吃完就看着窗外。"},{"t":"n","text":"过了一会儿，他说：「你上午看的那个公式，用错了。」"},{"t":"n","text":"你说：「哪个？」"},{"t":"n","text":"他用筷子在桌面上画了一个符号。"},{"t":"c","id":"luchen","text":"这个。指数不能那么拆。"},{"t":"n","text":"画完，他把筷子放好。"},{"t":"c","id":"luchen","text":"下午我给你写一遍。"}],"id":"luchen_05"},{"no":6,"title":"分科表","week":2,"bg":"corridor_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"分科表发下来，一张A4纸，两个方框。"},{"t":"n","text":"班主任说：「想清楚。这一勾，管两年。」"},{"t":"n","text":"走廊上贴了去年的分科数据：理科一本率，文科一本率。数字用红笔标了。"},{"t":"n","text":"他站在那张纸前面。"},{"t":"n","text":"你走过去，他往旁边让了半步。"},{"t":"c","id":"luchen","text":"你选什么。"},{"t":"n","text":"你说还没想好。"},{"t":"n","text":"他把手里的表递过来。他已经填完了。"},{"t":"n","text":"「理科」。两个字，写得很正。"},{"t":"n","text":"你看着那张表，发现背面还有字。翻过来，是一道题的解题过程，写了一半。"},{"t":"n","text":"他把表拿回去。"},{"t":"c","id":"luchen","text":"拿错了。那张是草稿。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说你也想选理科","hint":"跟他走同一条 · 不全为他","eff":{"aff":5.0,"int":3.0,"stress":2.0},"reply":[{"t":"n","text":"你说：「我也填理科。」"},{"t":"n","text":"他把表折起来，折成很小的一块，塞进裤兜。"},{"t":"c","id":"luchen","text":"想清楚。理科不是聪明就能读。"},{"t":"n","text":"你说你想清楚了。"},{"t":"n","text":"他看了你一会儿。"},{"t":"c","id":"luchen","text":"那行。"},{"t":"n","text":"他往教室走，走了两步，回头。"},{"t":"c","id":"luchen","text":"有不懂的，问我。"},{"t":"n","text":"他补了一句：「别问太基础的。」"}]},{"label":"B","text":"说你还在犹豫","hint":"先承认没想好 · 也算诚实","eff":{"aff":2.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你说你还在犹豫。"},{"t":"n","text":"他点点头，没有劝。"},{"t":"c","id":"luchen","text":"犹豫就还没到截止。"},{"t":"n","text":"你说：「可我怕选错。」"},{"t":"n","text":"他看着走廊尽头，那边是操场。"},{"t":"c","id":"luchen","text":"选错了，也就是两年。"},{"t":"n","text":"他说完，好像觉得这句话不太对，补了一句。"},{"t":"c","id":"luchen","text":"我瞎说的。"},{"t":"n","text":"那是他第一次承认自己说的话不算数。"}]},{"label":"C","text":"问他为什么不选文科","hint":"问他的理由 · 会听见真话","eff":{"aff":4.0,"eq":3.0,"stress":1.0},"reply":[{"t":"n","text":"你问：「你语文那么好，为什么不选文科。」"},{"t":"n","text":"他把表举起来，对着光看了一眼，像在检查有没有写错。"},{"t":"c","id":"luchen","text":"我爸教物理。"},{"t":"n","text":"「所以呢？」"},{"t":"n","text":"他把表放下。"},{"t":"c","id":"luchen","text":"他教过的学生里，学文的，一个都没有。"},{"t":"n","text":"走廊上有人跑过去，脚步声很响。"},{"t":"n","text":"他忽然说：「其实我想过。」"},{"t":"n","text":"「想过什么？」"},{"t":"c","id":"luchen","text":"想过学文。"},{"t":"n","text":"他说完就不说了，把表折好，塞进口袋。"}]}]},{"t":"n","text":"截止那天下午，你把表交了上去。"},{"t":"n","text":"班主任收表的时候翻了一下，说：「你们俩都理科，挺好，有个伴。」"},{"t":"n","text":"你回到教室，他已经在做题了。"},{"t":"n","text":"桌上放着一张纸，是从练习册上撕下来的，上面画了一张表格。"},{"t":"n","text":"表格里是高二物理的目录，每一章后面标了天数。"},{"t":"n","text":"最下面一行写着：「寒假之前做完。」"},{"t":"n","text":"你把那张纸折好，放进了课本里。"},{"t":"n","text":"九月的最后一天，放学以后他留在教室。你收拾东西的时候，他叫了你一声。"},{"t":"c","id":"luchen","text":"等一下。"},{"t":"n","text":"他从书包里拿出一本练习册，翻到中间。"},{"t":"c","id":"luchen","text":"这一章，你看得懂吗。"},{"t":"n","text":"你看了两分钟。半懂。"},{"t":"n","text":"你没有说话。他也没有催。"},{"t":"n","text":"过了一会儿，他把练习册转过去，在空白处写。"},{"t":"n","text":"他写得很快，一行一行往下。写完，他把本子推回来。"},{"t":"c","id":"luchen","text":"这一步，书上是跳的。我补上了。"},{"t":"n","text":"你看着那几行字。他的字很小，很用力，笔画像在往纸里压。"},{"t":"n","text":"「你为什么给我补。」你问。"},{"t":"n","text":"他把笔帽扣上。"},{"t":"c","id":"luchen","text":"因为我们选了同一条路。"},{"t":"n","text":"他说完，站起来，把书包背上。"},{"t":"c","id":"luchen","text":"路上不会只有一个人。"},{"t":"n","text":"那天你们一起下楼。楼道里的灯是坏的，他走在前面，替你把每一级台阶都数了一遍。"},{"t":"n","text":"到一楼，他停下来。"},{"t":"c","id":"luchen","text":"四十八级。以后你走的时候就知道了。"},{"t":"n","text":"你数了一次。真的四十八级。最后一级比别的矮半寸，容易绊到。"},{"t":"n","text":"第二天早上你差点绊了一下。一只手从后面扶住你的书包带。"},{"t":"n","text":"你回头。他跟你一起上楼，手里两杯豆浆。"},{"t":"c","id":"luchen","text":"最后一级，矮。"},{"t":"n","text":"你说：「你怎么知道。」"},{"t":"c","id":"luchen","text":"我数过。"},{"t":"n","text":"他把一杯豆浆递给你。"},{"t":"c","id":"luchen","text":"七点二十开门。你以后不用那么早。"},{"t":"n","text":"你说：「那你呢。」"},{"t":"n","text":"他往上走了两级，没有回头。"},{"t":"c","id":"luchen","text":"我早惯了。"}],"id":"luchen_06"},{"no":7,"title":"第一次大考","week":4,"bg":"classroom","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"第一次大考考三天。考完那天下午，走廊上的垃圾桶里全是草稿纸。"},{"t":"n","text":"成绩贴在教室后面的墙上。班主任念名字，从后往前念。"},{"t":"n","text":"第五，第四，第三。"},{"t":"n","text":"第二是你。"},{"t":"n","text":"你听见自己的名字，愣了一下。"},{"t":"n","text":"第一是他。"},{"t":"n","text":"下课，走廊上很多人。有人拍你的肩，说「可以啊」。你笑了笑。"},{"t":"n","text":"你回头找他。他站在成绩单前面，背对着你。"},{"t":"n","text":"他看的是第二行。"},{"t":"n","text":"你走过去。他没有转身。"},{"t":"c","id":"luchen","text":"你理综比我高四分。"},{"t":"n","text":"你说：「你总分比我高六分。」"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"他把手插进口袋，转过身来。"},{"t":"c","id":"luchen","text":"你的物理最后一道，怎么做的。"},{"t":"n","text":"你说了一遍。他听着，眼睛看着你的手。"},{"t":"n","text":"讲完，他从口袋里拿出一张纸。是他自己的草稿，上面画着同一道题的图。"},{"t":"n","text":"他画的方法跟你的不一样。他的更短。"},{"t":"n","text":"他把两张纸并在一起看。"},{"t":"c","id":"luchen","text":"你这个方法，通用。"},{"t":"n","text":"你问：「你的呢？」"},{"t":"c","id":"luchen","text":"我这个快。但只能用来做这一类。"},{"t":"n","text":"他把你的那张纸折起来，放进自己的口袋。"},{"t":"c","id":"luchen","text":"借我两天。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「你拿去，不用还」","hint":"把东西给他 · 也把话递过去","eff":{"aff":5.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你说：「你拿去，不用还。」"},{"t":"n","text":"他看了你一眼。"},{"t":"c","id":"luchen","text":"我会还。"},{"t":"n","text":"第二天早上，那张纸回到了你桌上，被压在一本练习册下面。"},{"t":"n","text":"纸的背面多了两行字。一行是他写的方法，一行是「这个方法有边界，别乱用」。"},{"t":"n","text":"最下面还有一个很小的字：「谢。」"},{"t":"n","text":"那个字没写完，捺拖得很短。"}]},{"label":"B","text":"问他：「你是不是不服气」","hint":"把话说破 · 会听见实话","eff":{"aff":4.0,"eq":3.0,"happy":-1.0},"reply":[{"t":"n","text":"你问：「你是不是不服气。」"},{"t":"n","text":"他把纸收回去，慢慢折起来。"},{"t":"c","id":"luchen","text":"不服气什么。"},{"t":"n","text":"「第二。」"},{"t":"n","text":"他沉默了几秒。"},{"t":"c","id":"luchen","text":"我从小到大，第二名的次数，一只手数得出来。"},{"t":"n","text":"他说完，把折好的纸塞进口袋。"},{"t":"c","id":"luchen","text":"现在多了一次。"},{"t":"n","text":"他往教室走。走了两步，停下。"},{"t":"c","id":"luchen","text":"你理综那四分，不是运气。"}]},{"label":"C","text":"说「下次我让你」","hint":"开个玩笑 · 气氛会变","eff":{"aff":-3.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"你说：「下次我让你。」"},{"t":"n","text":"他抬起头。"},{"t":"n","text":"他没有生气。他只是很平静地看着你。"},{"t":"c","id":"luchen","text":"你让我的东西，我不要。"},{"t":"n","text":"他把那张纸还给你，压在你桌上，手按了一下。"},{"t":"c","id":"luchen","text":"下次，凭本事。"},{"t":"n","text":"那天晚自习，他做题做到十一点。教室的灯关了一半，他还在。"},{"t":"n","text":"你走的时候，他忽然说：「你今天那句话，我记着了。」"},{"t":"n","text":"你说：「哪句？」"},{"t":"n","text":"他没有回答。"}]}]},{"t":"n","text":"十月末，学校组织了一次竞赛选拔。名单贴在办公室门口。"},{"t":"n","text":"上面有三个名字。第一个是他，第二个是你。"},{"t":"n","text":"第三个名字后面画了一个问号，被红笔圈了起来。"},{"t":"n","text":"选拔在周六。你在教室门口碰见他，他手里拿着一沓卷子。"},{"t":"c","id":"luchen","text":"周六，八点。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他把卷子分了一半给你。"},{"t":"c","id":"luchen","text":"先做这个。做完对答案。"},{"t":"n","text":"你问：「对完呢？」"},{"t":"c","id":"luchen","text":"对完，再做一遍。"},{"t":"n","text":"他说这话的时候，眼睛看着卷子。"},{"t":"n","text":"后来你才知道，那沓卷子是他自己印的。他父亲的办公室有一台复印机。"},{"t":"n","text":"他用一个下午，印了三十年真题。"},{"t":"n","text":"周六早上八点，实验楼的门还没开。他站在台阶上等，手里一沓卷子。"},{"t":"n","text":"你们做到中午。他把两张卷子并排放在一起对答案。"},{"t":"n","text":"你的最后一题错了。他的最后一题也错了。错在同一个地方。"},{"t":"n","text":"他看了很久。"},{"t":"c","id":"luchen","text":"这道题，出题的人自己也没想清楚。"},{"t":"n","text":"你说：「那怎么算。」"},{"t":"c","id":"luchen","text":"算他对。考试不改题。"},{"t":"n","text":"他把两张卷子叠起来，收进包里。"},{"t":"c","id":"luchen","text":"但我们要知道，他错了。"},{"t":"n","text":"他把卷子收好，站起来，走到窗边。"},{"t":"n","text":"窗外在下雪。今年的第一场，很小，落在窗台上就化了。"},{"t":"c","id":"luchen","text":"下雪了。"},{"t":"n","text":"他说这句话的时候，声音比平时软一点。"}],"id":"luchen_07"},{"no":8,"title":"集训队","week":19,"bg":"classroom","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"竞赛选拔的成绩贴在办公室门口。三个人，从上往下。"},{"t":"n","text":"第一，陆沉。第二，别班的一个人。第三，另一个人。"},{"t":"n","text":"你不在上面。"},{"t":"n","text":"你差了零点五分。"},{"t":"n","text":"那天放学，你在教室里收拾东西。人走光了，窗外的天是灰的。"},{"t":"n","text":"他站在名单前面，站了很久。你从走廊那头看见他的背影。"},{"t":"n","text":"然后他转身，往教室走。"},{"t":"n","text":"他进来的时候没有敲门。他把书包放在桌上，从里面拿出一沓纸。"},{"t":"c","id":"luchen","text":"集训的题。每天一套。"},{"t":"n","text":"你说：「我又没进队。」"},{"t":"c","id":"luchen","text":"没进，也可以做。"},{"t":"n","text":"他把纸放在你桌上，压上一支笔。"},{"t":"c","id":"luchen","text":"做完给我。我批。"},{"t":"n","text":"你看着那沓纸。纸是新的，边角很齐，是他用裁纸刀裁的。"},{"t":"n","text":"你问：「为什么。」"},{"t":"n","text":"他把书包拉链拉上。"},{"t":"c","id":"luchen","text":"我一个人做，也没意思。"},{"t":"n","text":"他说完就走了。走到门口，又回来。"},{"t":"c","id":"luchen","text":"明天开始。早上七点。"},{"t":"n","text":"集训在实验楼顶层。暖气不好，靠窗的位置冷。"},{"t":"n","text":"第二天早上你到的时候，桌上已经放了一杯豆浆。用保温杯装的，还热。"},{"t":"n","text":"旁边压着一张纸条：「喝完再做题。」"},{"t":"n","text":"你抬头。他坐在另一头，低头写题，围巾没有摘。"},{"t":"n","text":"之后的一个月，你们每天早到四十分钟。他做完一套，你做完一套，然后交换。"},{"t":"n","text":"他的批改很简短。「这里跳步」「这步没必要」「这个写法，抄三遍」。"},{"t":"n","text":"有一次你问他：「你自己不练？」"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"luchen","text":"我练完了。"},{"t":"n","text":"「几点。」"},{"t":"c","id":"luchen","text":"五点到六点。"},{"t":"n","text":"你说：「你几点睡。」"},{"t":"n","text":"他没有回答。他把你的卷子推回来，上面圈了三个地方。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"每天提早半小时，跟他一起做","hint":"把时间对上 · 一起熬","eff":{"aff":6.0,"int":4.0,"stress":3.0,"happy":1.0},"reply":[{"t":"n","text":"第二天你六点半到。实验楼的门还没开，楼道里只有应急灯。"},{"t":"n","text":"他站在门口，手里拿着两杯豆浆。"},{"t":"n","text":"看见你，他愣了一下。"},{"t":"c","id":"luchen","text":"你来这么早干嘛。"},{"t":"n","text":"你说：「跟你一起。」"},{"t":"n","text":"他没有说话。他把一杯豆浆递过来，自己拿着另一杯，靠着墙站着喝。"},{"t":"n","text":"门开的时候，他的杯子已经空了。"},{"t":"n","text":"那年冬天，你们在实验楼顶层待了四十六个早上。"},{"t":"n","text":"后来你算过，他每天比原来少睡半小时。为了等你。"}]},{"label":"B","text":"把卷子做完，但不再早到","hint":"守住自己的节奏 · 稳一点","eff":{"aff":2.0,"int":3.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"你照常七点二十到。桌上的豆浆还是热的。"},{"t":"n","text":"他没有问为什么。他只是把批好的卷子放在你桌上。"},{"t":"n","text":"有一天，你来得比平常早，七点。他已经在做了。"},{"t":"n","text":"他抬起头，看见你，说了一句：「今天早。」"},{"t":"n","text":"你说：「偶尔。」"},{"t":"n","text":"他点点头，把旁边那把椅子往外挪了一点。"},{"t":"n","text":"那天你们一句话也没说，做到上课铃响。"},{"t":"n","text":"走的时候，他把那张纸条从你桌上拿走，扔进了垃圾桶。"},{"t":"n","text":"你后来才知道，那张纸条他每天写一张。"}]},{"label":"C","text":"跟他说，别管我了","hint":"把距离划清 · 有点伤","eff":{"aff":-4.0,"happy":-2.0,"stress":-3.0},"reply":[{"t":"n","text":"你说：「你别管我了。你自己也要练。」"},{"t":"n","text":"他把批到一半的卷子停下。"},{"t":"n","text":"他抬起头，看了你几秒。"},{"t":"c","id":"luchen","text":"我没管你。"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"luchen","text":"我只是把题放你桌上。做不做是你的事。"},{"t":"n","text":"那天他没有再说话。第二天，桌上还是有豆浆。"},{"t":"n","text":"但纸条没有了。"},{"t":"n","text":"他把每天一套改成每天两套，两套都放在你桌上，没有批。"}]}]},{"t":"n","text":"一月，省赛的结果下来。他拿了第一。"},{"t":"n","text":"名单贴在公告栏上，只有一行。你去看的时候，他也在。"},{"t":"n","text":"他看完，转身，把手里的一张纸递给你。"},{"t":"n","text":"是省赛的卷子。整张卷子，被他用铅笔重新抄了一遍。"},{"t":"n","text":"每道题的旁边，都写着两种解法。一种是他的，一种是他猜你会用的。"},{"t":"n","text":"你说：「我又不去比赛。」"},{"t":"n","text":"他把手插进口袋。"},{"t":"c","id":"luchen","text":"你以后会遇到。"},{"t":"n","text":"那天风很大。他把围巾往上拉了拉，遮住半张脸。"},{"t":"n","text":"走了几步，他回头。"},{"t":"c","id":"luchen","text":"下次，你自己进队。"},{"t":"n","text":"你说：「那你呢。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"luchen","text":"我在队里等你。"}],"id":"luchen_08"},{"no":9,"title":"毕业日","week":24,"bg":"sakura_path","cast":["sunian","luchen"],"steps":[{"t":"cast","list":["sunian","luchen"],"focus":"sunian"},{"t":"n","text":"高考最后一科结束，校门口全是人。有人抱着花，有人抱着同学。"},{"t":"n","text":"你从考场出来，太阳很晒，眼睛有一会儿看不清东西。"},{"t":"n","text":"他站在校门右边的梧桐下面。"},{"t":"n","text":"白衬衫，袖子卷到手肘。他手里没有花，也没有手机。"},{"t":"n","text":"你走过去。他先开口。"},{"t":"c","id":"luchen","text":"最后一题。"},{"t":"n","text":"你说：「这次你做出来了吧。」"},{"t":"c","id":"luchen","text":"做出来了。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"luchen","text":"跟你初中那个方法一样。"},{"t":"n","text":"你们站在树下面。蝉叫得很响，一阵一阵，中间有停顿。"},{"t":"n","text":"「估分了吗。」他问。"},{"t":"n","text":"你说估了。"},{"t":"n","text":"他点头，没有再问。"},{"t":"n","text":"过了一会儿，他说：「我报了北边那所。」"},{"t":"n","text":"你知道那所。墙上七张纸里，最旧的那一张。"},{"t":"n","text":"「你呢。」他问。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说你也报了同一座城市","hint":"往他那边走一步 · 别说为他","eff":{"aff":7.0,"happy":4.0,"stress":2.0},"reply":[{"t":"n","text":"你说你报了同一座城市。不是同一所，但坐地铁四十分钟。"},{"t":"n","text":"他看着你，看了很久。"},{"t":"c","id":"luchen","text":"为什么。"},{"t":"n","text":"你说：「那个城市好。」"},{"t":"n","text":"他低下头，笑了一下。很轻，只有嘴角动。"},{"t":"c","id":"luchen","text":"嗯。挺好。"},{"t":"n","text":"他从书包里拿出一张纸。是从作业本上撕下来的，折了三折。"},{"t":"c","id":"luchen","text":"地址。学校宿舍。"},{"t":"n","text":"你接过来。纸上有他的字，很小，很用力。"},{"t":"n","text":"最下面还有一行：「写信。别打电话，宿舍电话要排队。」"}]},{"label":"B","text":"说你还没定","hint":"先不说死 · 留个口子","eff":{"aff":2.0,"happy":-1.0,"stress":1.0},"reply":[{"t":"n","text":"你说还没定。"},{"t":"n","text":"他「嗯」了一声。"},{"t":"n","text":"蝉还在叫。你们站了一会儿，谁都没说话。"},{"t":"n","text":"他说：「定了告诉我。」"},{"t":"n","text":"「怎么告诉。」"},{"t":"n","text":"他从口袋里摸出一支笔，把笔帽咬开，在你手心里写了一串数字。"},{"t":"n","text":"是宿舍的电话号码。"},{"t":"c","id":"luchen","text":"打通了找三零四。"},{"t":"n","text":"笔尖有点凉。写完他把笔收回去，你的手心留了一道蓝。"}]},{"label":"C","text":"说你要留在本城","hint":"留在熟悉的地方 · 也有代价","eff":{"aff":3.0,"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你说你要留在本城。"},{"t":"n","text":"他点点头。"},{"t":"c","id":"luchen","text":"本城那所，物理系也不错。"},{"t":"n","text":"你说：「你查过？」"},{"t":"n","text":"他没有回答。他把视线移到操场上。"},{"t":"c","id":"luchen","text":"查过。"},{"t":"n","text":"操场上有人在拍照，喊「再来一张」。"},{"t":"n","text":"他忽然说：「四年。」"},{"t":"n","text":"「什么四年。」"},{"t":"c","id":"luchen","text":"四年以后，我去找你。"},{"t":"n","text":"他说得很平静，像在说一件已经安排好的事。"}]}]},{"t":"n","text":"班主任在门口喊集合，拍毕业照。"},{"t":"n","text":"队伍排成三排。他被安排在第一排最右边，你在第二排中间。"},{"t":"n","text":"摄影师喊「三、二、一」。所有人都在笑。"},{"t":"n","text":"快门响的时候，你看见他往你这边看了一眼。"},{"t":"n","text":"照片洗出来，他那一张脸是侧着的，被后排的人挡住了一半。"},{"t":"n","text":"散场以后，你在校门口又碰见他。"},{"t":"n","text":"他手里多了一个纸袋。"},{"t":"c","id":"luchen","text":"这个给你。"},{"t":"n","text":"你打开。是那本深蓝的旧笔记。"},{"t":"n","text":"你说：「这个不是你的？」"},{"t":"c","id":"luchen","text":"是我的。"},{"t":"n","text":"他把手插回口袋。"},{"t":"c","id":"luchen","text":"先放你那儿。我的书太多了，装不下。"},{"t":"n","text":"你知道他在说谎。他的书包是空的。"},{"t":"n","text":"你把书抱在怀里。"},{"t":"n","text":"他抬手看了一眼表。还是那块旧的，表盘上有划痕。"},{"t":"n","text":"「几点了。」你问。"},{"t":"n","text":"他看了一眼，说：「四点二十七。」"},{"t":"n","text":"你低头看自己的表。四点三十。"},{"t":"n","text":"你没有说。"},{"t":"n","text":"那天以后，你才知道他的表慢三分钟。他从来不修。"},{"t":"n","text":"暑假里，你们通过两次电话。第一次说志愿，第二次说天气。"},{"t":"n","text":"第二次通话快结束的时候，他忽然问：「你什么时候走。」"},{"t":"n","text":"你说了日期。电话那头安静了几秒。"},{"t":"n","text":"「怎么，」你问，「你要送？」"},{"t":"n","text":"他说：「不送。」"},{"t":"n","text":"又过了两秒。"},{"t":"c","id":"luchen","text":"我那天有课。"},{"t":"n","text":"后来你在站台上没有看见他。开车前五分钟，手机响了。"},{"t":"n","text":"「到了发消息。」"},{"t":"n","text":"你回了一个「好」字。他没有再回。"}],"id":"luchen_09"}]},{"id":"ch2","title":"第二章 · 大学","scenes":[{"no":10,"title":"一张座位号","week":25,"bg":"bedroom_day","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"报到那天，宿舍在六楼，没有电梯。"},{"t":"n","text":"你把箱子一级一级提上去，手心磨出一道红印。"},{"t":"n","text":"四个人一间。你到得最晚，靠门的那张床空着，床板上有一层灰。"},{"t":"n","text":"铺床的时候，手机在口袋里震了一下。"},{"t":"n","text":"是一条陌生号码的短信：「三零四，靠窗第三个。明天七点开馆。」"},{"t":"n","text":"你看着那串数字。是他。"},{"t":"n","text":"你回：「你怎么知道我的号。」"},{"t":"n","text":"过了十分钟，他回：「问的。」"},{"t":"n","text":"又过了两分钟，他补了一条：「你妈给的。」"},{"t":"n","text":"你把手机放在床板上，坐下来，忽然觉得有点想笑。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"第二天七点到图书馆","hint":"按他说的做 · 早一点","eff":{"aff":6.0,"int":3.0,"happy":3.0},"reply":[{"t":"n","text":"图书馆七点开馆。你六点五十到，门口已经排了十几个人。"},{"t":"n","text":"七点整，门开。上三楼，靠窗第三个位置空着，桌上放着一本书，压着一张纸。"},{"t":"n","text":"纸上写着：「这个位置，我占到了。」"},{"t":"n","text":"你坐下。八点，他才来。"},{"t":"n","text":"他背着书包，头发有一点乱，像是跑过来的。"},{"t":"c","id":"luchen","text":"路上堵了。"},{"t":"n","text":"他把书包放下，坐在你对面。"},{"t":"n","text":"你们一句话也没说，做到中午。"}]},{"label":"B","text":"回一句「太早了」，继续睡","hint":"先顾自己 · 也不勉强","eff":{"aff":1.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你回：「七点太早了。」然后把手机扣在枕头边。"},{"t":"n","text":"第二天你十点才去图书馆。三楼靠窗第三个位置空着，桌上压着一张纸。"},{"t":"n","text":"纸上写着：「位置留到九点。明天还是七点。」"},{"t":"n","text":"你抬头看四周。没有他。"},{"t":"n","text":"你把那张纸翻过来，背面有一行更小的字：「你要是不来，我就自己坐。」"}]},{"label":"C","text":"问他，为什么是图书馆","hint":"问一句 · 会听见他的说法","eff":{"aff":3.0,"eq":3.0,"happy":1.0},"reply":[{"t":"n","text":"你回：「为什么是图书馆。」"},{"t":"n","text":"他回得很快：「安静。」"},{"t":"n","text":"你又问：「就这个？」"},{"t":"n","text":"这次他过了很久才回。"},{"t":"n","text":"「书多。」"},{"t":"n","text":"再过了两分钟，又来一条。"},{"t":"n","text":"「而且，你做题的时候不说话。」"},{"t":"n","text":"你看着这条短信，看了很久。"},{"t":"n","text":"最后一条：「这样我能坐久一点。」"}]}]},{"t":"n","text":"大学第一个月，你收到了三封信。都是手写的，信封上贴着邮票。"},{"t":"n","text":"第一封写的是课表。第二封写的是他宿舍楼下的猫。"},{"t":"n","text":"第三封只有一张纸，上面是一道题，和一句话：「做出来给我看。」"},{"t":"n","text":"你把那道题做了三天。做出来那天，你去了图书馆三楼。"},{"t":"n","text":"靠窗第三个位置空着。你把答案放在桌上，坐下来等。"},{"t":"n","text":"他八点到。看见桌上的纸，先看答案，再看你。"},{"t":"c","id":"luchen","text":"第三天。"},{"t":"n","text":"你说：「这题有点意思。」"},{"t":"n","text":"他把纸折好，放进口袋。"},{"t":"c","id":"luchen","text":"明天，还有一道。"},{"t":"n","text":"那道题做出来之后，你把答案夹在书里，去图书馆等他。"},{"t":"n","text":"他那天没来。"},{"t":"n","text":"第二天也没来。"},{"t":"n","text":"第三天，桌上的答案不见了。换成一张纸，上面写着：「看过了。第三行可以更短。」"},{"t":"n","text":"你抬头看四周。靠窗第三个位置空着，台灯没关。"},{"t":"n","text":"他坐在最里面那一排，背对着你。"},{"t":"n","text":"你走过去。他没有回头。"},{"t":"c","id":"luchen","text":"那个位置，光线好。你坐。"},{"t":"n","text":"你说：「那你呢。」"},{"t":"n","text":"他翻了一页书。"},{"t":"c","id":"luchen","text":"我坐哪儿都一样。"},{"t":"n","text":"你把答案留在那张桌上，回到自己原来的位置。"},{"t":"n","text":"下午三点，那张纸被推了回来。背面多了一行字：「椅子空着，是浪费。」"},{"t":"n","text":"你又搬了回去。"},{"t":"block","when":"mainvariant","minAff":null,"steps":[{"t":"n","text":"你的学校在城东，他的在城西。地铁四十分钟，中间换一次。"},{"t":"n","text":"他发来的第二条短信是：「周末，图书馆三楼。你们学校那个。」"},{"t":"n","text":"你回：「你怎么进得来。」"},{"t":"n","text":"他回：「登记。我说找同学。」"},{"t":"n","text":"第三条：「能进。」"}]}],"id":"luchen_10"},{"no":11,"title":"图书馆三楼","week":26,"bg":"library_day","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"十月，雨下了三天。图书馆三楼的窗子关不严，靠窗的位置会渗水。"},{"t":"n","text":"他还是坐那儿。桌上摊着三本书：一本竞赛题，一本专业课本，还有一本很旧。"},{"t":"n","text":"那本旧的，书脊用透明胶粘过。"},{"t":"n","text":"你坐过去。他头也没抬，把最旧的那本往你那边推了推。"},{"t":"c","id":"luchen","text":"第三题。你上次错了。"},{"t":"n","text":"你翻开。扉页上有一个名字，被涂掉了，又写上一个新的。"},{"t":"n","text":"「陆沉」。字很小，很用力。"},{"t":"n","text":"窗外在下雨。雨点打在玻璃上，一道一道往下爬。"},{"t":"n","text":"你做题。他做题。中间隔着一盏台灯，灯罩歪了，光往他那边偏。"},{"t":"n","text":"你伸手把灯罩掰正。他抬起头。"},{"t":"n","text":"他没有说谢谢。他把灯罩又掰回了一点。"},{"t":"c","id":"luchen","text":"这样，两个人都有光。"},{"t":"n","text":"第三题你做了四十分钟。他做二十分钟。"},{"t":"n","text":"做完，他把你的本子拿过去，看了两分钟，圈出三个地方。"},{"t":"c","id":"luchen","text":"这里，你多算了一步。"},{"t":"n","text":"你说：「多算一步怎么了。」"},{"t":"c","id":"luchen","text":"浪费时间。"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"luchen","text":"考试的时候，多算一步，就是少做一道题。"},{"t":"n","text":"你没有说话。你把那三个地方重算了一遍。"},{"t":"n","text":"做到闭馆，管理员来关灯。她还隔着两排书架喊了一声「还有人吗」。"},{"t":"n","text":"他这才抬起头，像是刚想起旁边还有一个人。"},{"t":"n","text":"收拾东西的时候，他的手机亮了。"},{"t":"n","text":"屏幕上是一条消息。备注是「爸」。"},{"t":"n","text":"他看了一眼，按灭，把手机扣在桌上。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"陪他坐到闭馆","hint":"陪他把题做完 · 智力 ↑","eff":{"aff":6.0,"int":3.0,"stress":2.0,"happy":1.0},"reply":[{"t":"n","text":"你说：「那就再做一道。」"},{"t":"n","text":"他看了你一会儿，从包里把书又拿了出来。"},{"t":"n","text":"你们把最后一道题拆成三步。他讲得很快，你听不懂的地方，他就再讲一遍，没有不耐烦。"},{"t":"n","text":"讲第二遍的时候，他放慢了速度，一个字一个字地说。"},{"t":"n","text":"你忽然发现，他讲题的时候，声音跟平时不一样。"},{"t":"n","text":"他把外套脱下来，搭在椅背上，没有给你。"},{"t":"n","text":"但椅子往你这边挪了半尺。"},{"t":"n","text":"到门口，雨还在下。他把伞递给你。"},{"t":"c","id":"luchen","text":"拿着。明天还我。"},{"t":"n","text":"你说：「明天可能下雨。」"},{"t":"c","id":"luchen","text":"那就后天还。"}]},{"label":"B","text":"问他，为什么总要做到最好","hint":"问一句 · 情商 ↑","eff":{"aff":5.0,"eq":3.0,"happy":1.0},"reply":[{"t":"n","text":"你问：「你为什么总要做到最好。」"},{"t":"n","text":"他沉默了一会儿。雨声很大，把图书馆的安静填满了。"},{"t":"c","id":"luchen","text":"因为第二名没人记得。"},{"t":"n","text":"你说：「我记得。」"},{"t":"n","text":"他看了你一眼。那一眼很长。"},{"t":"n","text":"他把书合上。"},{"t":"c","id":"luchen","text":"你记得没用。"},{"t":"n","text":"「为什么没用？」"},{"t":"c","id":"luchen","text":"因为你也会走。"},{"t":"n","text":"他说完，把书塞进包里，站起来。"},{"t":"n","text":"那天晚上，他走得很慢。从图书馆到宿舍，平时十分钟的路，走了二十分钟。"},{"t":"n","text":"到岔路口，他停下来。"},{"t":"c","id":"luchen","text":"明天几点。"}]},{"label":"C","text":"先走，让他自己忙","hint":"不打扰 · 心情 ↑","eff":{"aff":-2.0,"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你说你先走了。他「嗯」了一声，没有抬头。"},{"t":"n","text":"第二天，你桌上多了一张纸条：「第三题，自己先想。」"},{"t":"n","text":"纸条背面，画了一个很小的、歪歪扭扭的伞。"},{"t":"n","text":"伞下面画了一条线。线的尽头是一个点。"},{"t":"n","text":"你没有看懂。你把纸条夹在书里。"},{"t":"n","text":"一个星期后，那张纸条的折痕处已经磨白了。"}]}]},{"t":"block","when":"flag1","steps":[{"t":"n","text":"走到门口，雨小了一点。他把伞撑开，又收起来。"},{"t":"n","text":"然后他从包里拿出那本深蓝的旧笔记，塞给你。"},{"t":"n","text":"封皮上贴着一张新的标签，上面写着你的名字。字很小，很用力。"},{"t":"n","text":"你翻开。扉页上，那个被涂掉的名字旁边，「陆沉」两个字也被涂掉了。"},{"t":"n","text":"涂掉的地方，写着你的名字。"},{"t":"c","id":"luchen","text":"别掉队。"},{"t":"n","text":"你抬头。他已经撑开伞走进雨里。"},{"t":"n","text":"伞是黑的，很快就看不见了。"},{"t":"n","text":"你站在图书馆的台阶上，把笔记翻开。"},{"t":"n","text":"里面每一页的空白处，都写着两种解法。一种是他的，一种是他猜你会用的。"},{"t":"n","text":"有一页的边上，写着一行小字：「这个人第三步会跳。要提醒。」"},{"t":"n","text":"翻到最后，夹着一张纸。纸上是一张课表。"},{"t":"n","text":"星期二、星期四的晚上，图书馆三楼，都画了一个圈。"},{"t":"n","text":"圈旁边写着：「这个时间，我在。」"}]},{"t":"block","when":"low","steps":[{"t":"n","text":"走到门口，他把伞撑开。"},{"t":"n","text":"他站在台阶上，看了看雨，又看了看你。"},{"t":"c","id":"luchen","text":"你带伞了吗。"},{"t":"n","text":"你说没带。"},{"t":"n","text":"他把伞往你那边偏了偏。"},{"t":"c","id":"luchen","text":"走吧。送到路口。"},{"t":"n","text":"你们走到路口。他把伞收起来，甩了两下。"},{"t":"c","id":"luchen","text":"那本旧的，下次给你。"},{"t":"n","text":"你问：「哪次。」"},{"t":"n","text":"他没有回答。他把伞夹在腋下，往雨里走了几步，又回头。"},{"t":"c","id":"luchen","text":"你那个第三步，还是会跳。自己注意。"},{"t":"n","text":"那天他没有给。后来的一个月，他也没有再提。"},{"t":"n","text":"但那本旧笔记，一直在他的书包里。你见过两次。"},{"t":"n","text":"每次他拉书包拉链，都会先看一眼，再拉上。"}]},{"t":"block","when":"aff","minAff":40,"steps":[{"t":"n","text":"你问：「不回去回一个？」"},{"t":"n","text":"他把书塞进包里。拉链拉了一半，卡住了。"},{"t":"n","text":"他用力扯了一下，没扯动。"},{"t":"n","text":"你伸手，把卡在拉链里的布料拽出来。他说了声「谢谢」，声音很低。"},{"t":"c","id":"luchen","text":"回了也是问排名。"},{"t":"n","text":"你说：「大学还有排名？」"},{"t":"c","id":"luchen","text":"有。他看得到。"},{"t":"n","text":"他把包背上。"},{"t":"c","id":"luchen","text":"他认识这边的老师。"},{"t":"n","text":"你们走到楼梯口。走廊的声控灯灭了，他抬脚跺了一下，灯又亮。"},{"t":"n","text":"他站在灯下面，忽然说：「你知不知道，我为什么总要做第一。」"},{"t":"n","text":"你摇头。"},{"t":"c","id":"luchen","text":"第二名，需要解释。"},{"t":"n","text":"他说完，往楼下走。"},{"t":"c","id":"luchen","text":"第一名不用。"}]}],"id":"luchen_11"},{"no":12,"title":"冬天的集训队","week":31,"bg":"classroom","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"集训队在实验楼顶层。冬天没有暖气，五个人挤在一间屋子里，呼出的气是白的。"},{"t":"n","text":"教练姓周，五十多岁，说话很慢。他第一次点名，点到陆沉，说：「你去年差一点。」"},{"t":"n","text":"陆沉说：「嗯。」"},{"t":"n","text":"「今年呢。」"},{"t":"n","text":"「今年拿回来。」"},{"t":"n","text":"集训分两组。你和他一组。另外三个人一组。"},{"t":"n","text":"白板只有一块。他写字，你擦板。写到第三周，你们不用说话了：他写完，手一伸，你把板擦递过去。"},{"t":"n","text":"有个队友说：「你们俩这样，谁赢都一样。」"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"luchen","text":"不一样。"},{"t":"n","text":"「哪儿不一样。」"},{"t":"c","id":"luchen","text":"赢了的人，才有资格说方法好。"},{"t":"n","text":"那天晚上，你们做到十二点。他送你到楼下。"},{"t":"n","text":"路灯坏了一盏，路面上一块亮一块黑。"},{"t":"n","text":"走到亮的地方，他忽然说：「初赛，你别让我。」"},{"t":"n","text":"你说：「我让不了你。」"},{"t":"n","text":"他停下脚步。"},{"t":"c","id":"luchen","text":"那就好。"},{"t":"n","text":"初赛在一月的第二个周六。考场在城北的一所中学，教室的暖气开得很足。"},{"t":"n","text":"进考场前，你摸书包，发现准考证不见了。"},{"t":"n","text":"他从后面走过来，把一张卡塞进你手里。"},{"t":"c","id":"luchen","text":"你昨天落在白板下面了。"},{"t":"n","text":"你说：「你怎么不早给我。」"},{"t":"c","id":"luchen","text":"早给你，你还会丢。"},{"t":"n","text":"他往自己的考场走。走了两步，回头。"},{"t":"c","id":"luchen","text":"别慌。前三道慢慢做。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"按他说的，前三道慢慢做","hint":"稳住开头 · 把节奏拿回来","eff":{"aff":5.0,"int":4.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"前三道你做了二十五分钟。做完，你抬头看了一眼钟，心定下来。"},{"t":"n","text":"后面的题一道一道往下走。最后一题你留了二十分钟。"},{"t":"n","text":"铃响的时候，你写完了最后一个字。"},{"t":"n","text":"出考场，他已经在楼下等了。"},{"t":"c","id":"luchen","text":"怎么样。"},{"t":"n","text":"你说：「做完了。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"我也是。"},{"t":"n","text":"你们并排走出校门。天很冷，路边的水洼结了冰。"},{"t":"n","text":"他忽然说：「你刚才那声叹气，我在隔壁听见了。」"}]},{"label":"B","text":"先做最后一道大题","hint":"先啃硬的 · 风险自己担","eff":{"aff":2.0,"int":2.0,"stress":4.0,"happy":-1.0},"reply":[{"t":"n","text":"你从最后一题开始。做了三十五分钟，卡在第二步。"},{"t":"n","text":"抬头看钟，还剩四十分钟。你回头做前面的题，手一直在抖。"},{"t":"n","text":"出考场的时候，你有一道半没做完。"},{"t":"n","text":"他在楼下。看见你的脸，他什么也没问。"},{"t":"n","text":"他把手里的热豆浆递过来。"},{"t":"c","id":"luchen","text":"先喝。"},{"t":"n","text":"你喝了一口，太烫，眼泪差点出来。"},{"t":"n","text":"他站在旁边，等你喝完。"},{"t":"c","id":"luchen","text":"下次，按顺序。"}]},{"label":"C","text":"深呼吸，从头检查一遍准考证","hint":"先确认东西 · 再进考场","eff":{"aff":3.0,"eq":2.0,"stress":-3.0,"happy":2.0},"reply":[{"t":"n","text":"你把准考证、笔、尺子一样一样摆在桌上，确认了一遍。"},{"t":"n","text":"监考老师发卷的时候，你已经不抖了。"},{"t":"n","text":"考完出来，他在楼下。"},{"t":"c","id":"luchen","text":"你进去之前，在门口站了很久。"},{"t":"n","text":"你说：「在数东西。」"},{"t":"n","text":"他看了你两秒。"},{"t":"c","id":"luchen","text":"这个习惯好。"},{"t":"n","text":"他说完，把手插进口袋。"},{"t":"c","id":"luchen","text":"我也是这样。"}]}]},{"t":"n","text":"初赛成绩出来，是三个星期以后的事。"},{"t":"n","text":"名单贴在实验楼一楼。人很多。你从人缝里挤进去。"},{"t":"n","text":"第一行：你。"},{"t":"n","text":"第二行：陆沉。"},{"t":"n","text":"你比他高三分。"},{"t":"n","text":"你回头。他站在人群外面，没有挤。"},{"t":"n","text":"他看了很久。然后他走过来。"},{"t":"n","text":"你等着他说点什么。他说的是一句你没想到的。"},{"t":"c","id":"luchen","text":"你第三步，是怎么想到的。"},{"t":"n","text":"你说了一遍。他听着，眉头慢慢松开。"},{"t":"c","id":"luchen","text":"这个，我没想到。"},{"t":"n","text":"他把手插进口袋，又拿出来。"},{"t":"c","id":"luchen","text":"这次，你赢。"},{"t":"n","text":"你说：「还有决赛。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"所以，别松。"},{"t":"n","text":"那天晚上，实验楼的灯亮到一点。他把你初赛的卷子重做了一遍。"},{"t":"n","text":"做完，他在最后一页写：「这个方法，我学走了。」"},{"t":"n","text":"他把卷子还给你的时候，那行字被划掉了。"},{"t":"n","text":"划掉以后，旁边重新写了一行：「我学不会。这是你的。」"}],"id":"luchen_12"},{"no":13,"title":"名单上没有你","week":35,"bg":"library_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"决赛名单贴出来的时候，你在第二页找了三遍。"},{"t":"n","text":"没有你。"},{"t":"n","text":"综合排名：初赛、实验操作、面试。三项加权。"},{"t":"n","text":"你初赛第一。实验操作那一项，你排第九。"},{"t":"n","text":"那天实验操作，你打碎了一个量筒。"},{"t":"n","text":"玻璃碎在地上的声音很轻。监考老师说「没关系，换一个」，但你后面的步骤全乱了。"},{"t":"n","text":"你花了三个月准备的东西，最后变成名单上别人的名字。"},{"t":"n","text":"你在公告栏前面站了很久。有人从你旁边过去，看了一眼，说「可惜」。"},{"t":"n","text":"你也可以说可惜。但你知道不是可惜。"},{"t":"n","text":"你转身的时候，眼前黑了一下。你扶着墙站了很久，才想起要呼吸。"},{"t":"n","text":"走廊尽头有人在拖地，拖把的水声一下一下。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"找人说话","hint":"说出来 · 压力 ↓","eff":{"aff":5.0,"eq":3.0,"happy":4.0,"stress":-8.0},"reply":[{"t":"n","text":"你给他发了消息：「名单出来了。」"},{"t":"n","text":"十分钟后他回：「在哪。」"},{"t":"n","text":"你们在操场边坐到很晚。他没有劝你。"},{"t":"n","text":"他把外套脱下来，放在你们中间的台阶上。"},{"t":"c","id":"luchen","text":"冷。"},{"t":"n","text":"你说：「我不冷。」"},{"t":"n","text":"他说：「我也不冷。」"},{"t":"n","text":"外套就那样放在中间，谁也没穿。"},{"t":"n","text":"过了很久，他说：「实验操作那一项，我第七。」"},{"t":"n","text":"你抬头。"},{"t":"c","id":"luchen","text":"我也不是第一。"},{"t":"n","text":"「可你进了。」"},{"t":"c","id":"luchen","text":"因为初赛。你初赛第一。"},{"t":"n","text":"他把手插进口袋。"},{"t":"c","id":"luchen","text":"这不公平。"},{"t":"n","text":"你说：「规则就是这样。」"},{"t":"n","text":"他沉默了一会儿。"},{"t":"c","id":"luchen","text":"规则不公平的时候，赢了的人不该装看不见。"}]},{"label":"B","text":"自己扛","hint":"不麻烦别人 · 压力 ↑","eff":{"int":3.0,"stress":9.0,"happy":-4.0,"aff":1.0},"reply":[{"t":"n","text":"你回到图书馆，把同一道题又做了一遍。"},{"t":"n","text":"做对的时候，你没有任何感觉。"},{"t":"n","text":"十一点闭馆。管理员来关灯，你已经把整本练习册做完了。"},{"t":"n","text":"出门的时候，台阶上坐着一个人。"},{"t":"n","text":"他站起来，把手里的东西递给你。是一瓶水。"},{"t":"c","id":"luchen","text":"你手上有玻璃碴。"},{"t":"n","text":"你低头。手背上有一道很细的口子，早就干了。"},{"t":"n","text":"他等了一会儿，见你不接，把水放在台阶上。"},{"t":"c","id":"luchen","text":"明天，还是七点。"}]},{"label":"C","text":"请一天假，去走走路","hint":"停下来 · 心情 ↑","eff":{"stress":-10.0,"happy":3.0,"str":2.0,"aff":2.0},"reply":[{"t":"n","text":"你翘了一天的课，坐公交到终点站，又坐回来。"},{"t":"n","text":"车窗外的城市一段一段往后退。"},{"t":"n","text":"你在一家便利店买了一瓶热豆浆，坐在路边喝完。没有人认识你。"},{"t":"n","text":"天黑的时候你回到学校。宿舍楼下站着一个人。"},{"t":"n","text":"他手里拿着两本书，看见你，把书往怀里收了收。"},{"t":"c","id":"luchen","text":"你一天没回消息。"},{"t":"n","text":"你说：「手机没电。」"},{"t":"n","text":"他看了你两秒，没有拆穿。"},{"t":"c","id":"luchen","text":"哦。"},{"t":"n","text":"他把其中一本书递给你。"},{"t":"c","id":"luchen","text":"明天的题。做不做随你。"}]}]},{"t":"n","text":"回宿舍的路上，手机震了一下。"},{"t":"n","text":"是那个赢了的人发来的：「你的方案，第二部分其实比我的好。」"},{"t":"n","text":"你看着这句话，站在路灯下面。"},{"t":"n","text":"你没有回。"},{"t":"n","text":"但你把那条消息截了图。"},{"t":"n","text":"第二天上课，他坐在你旁边。他把自己的笔记本推过来，翻到一页。"},{"t":"n","text":"那页上是他决赛的模拟方案。第二部分，被划掉了。"},{"t":"n","text":"旁边写着：「用你的。」"},{"t":"n","text":"你说：「你自己不是有？」"},{"t":"n","text":"他把本子拿回去。"},{"t":"c","id":"luchen","text":"我的不够好。"},{"t":"n","text":"他顿了一下，补了一句。"},{"t":"c","id":"luchen","text":"我不喜欢用不够好的东西。"},{"t":"n","text":"他说完，把本子收进包里。"},{"t":"n","text":"收拾东西的时候，他从抽屉深处拿出一样东西，放在桌上。"},{"t":"n","text":"是一个信封，已经封好，上面写着「初赛成绩复核」。"},{"t":"n","text":"你说：「你要申请复核？」"},{"t":"n","text":"他把信封拿起来。"},{"t":"c","id":"luchen","text":"实验操作那一项，评分表上有三处签名。"},{"t":"n","text":"「所以呢。」"},{"t":"n","text":"他看着信封。"},{"t":"c","id":"luchen","text":"一处是我的导师。一处是主办方。第三处，我看不清。"},{"t":"n","text":"他把信封放回抽屉。"},{"t":"c","id":"luchen","text":"算了。"},{"t":"n","text":"你说：「为什么。」"},{"t":"n","text":"他把抽屉关上。"},{"t":"c","id":"luchen","text":"因为就算复核了，第一名也不会是我。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"也不会是你。"},{"t":"n","text":"那天晚上，他在公告栏前面站了很久。你把那张复核表从他抽屉里拿出来，填了一半。"}],"id":"luchen_13"},{"no":14,"title":"实验楼门口","week":39,"bg":"campus_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"六月的晚上，风是热的。"},{"t":"n","text":"实验楼的灯还亮着。他关掉电脑，走出来，白衬衫袖口卷着。"},{"t":"n","text":"看见你，他停了一下，把袖口放下来，又觉得多余，重新卷上去。"},{"t":"c","id":"luchen","text":"有事？"},{"t":"n","text":"他站在台阶上，比你高半级。他没有下来的意思，也没有走。"},{"t":"n","text":"你手里攥着一样东西。"},{"t":"n","text":"是一张竞赛的报名表。初赛的，早过期了。"},{"t":"n","text":"你也不知道为什么带它来。"},{"t":"n","text":"「保研定了。」他说，「北边。」"},{"t":"n","text":"你说：「嗯。听说了。」"},{"t":"n","text":"「下个月走。」"},{"t":"n","text":"「嗯。」"},{"t":"n","text":"他把手插进口袋，又拿出来。"},{"t":"c","id":"luchen","text":"你有话说。"},{"t":"n","text":"不是问句。"},{"t":"n","text":"楼道的声控灯灭了。他抬脚跺了一下，灯亮起来，照见他的手。"},{"t":"n","text":"他的手指在轻微地动，像在算什么东西。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「好，但我也要改」","hint":"各退一步 · 关系才会长","eff":{"aff":6.0,"eq":4.0,"happy":3.0},"reply":[{"t":"n","text":"你说：「好。但我也有问题。」"},{"t":"n","text":"他抬头。"},{"t":"n","text":"你说：「我不高兴的时候不说。等攒够了才说。」"},{"t":"n","text":"他听着，点头。"},{"t":"c","id":"luchen","text":"那我们都改。"},{"t":"n","text":"他伸出手。你握上去。"},{"t":"n","text":"他的手很凉。握着握着，慢慢热了。"}]},{"label":"B","text":"说「这次算了」","hint":"先过去 · 以后再谈","eff":{"aff":2.0,"happy":-1.0,"stress":2.0},"reply":[{"t":"n","text":"你说：「这次算了。」"},{"t":"n","text":"他点头，说「好」。"},{"t":"n","text":"你们并排往回走。走到岔路口，他说：「你没算。」"},{"t":"n","text":"你说：「什么？」"},{"t":"c","id":"luchen","text":"你刚才说算了。但你没算。"},{"t":"n","text":"他停下脚步。"},{"t":"c","id":"luchen","text":"你不说，我会一直想。"}]},{"label":"C","text":"转身走","hint":"先冷静 · 让他自己想","eff":{"aff":-2.0,"happy":-2.0,"stress":3.0},"reply":[{"t":"n","text":"你转身就走。"},{"t":"n","text":"他没有追。"},{"t":"n","text":"你走到宿舍楼下，回头看了一眼。他还站在实验楼门口，灯在他身后。"},{"t":"n","text":"半小时后，手机亮了。"},{"t":"n","text":"「我在楼下。你不下来也行。我站到你想下来为止。」"}]}]},{"t":"block","when":"flag2","steps":[{"t":"n","text":"他握着你的手，站了一会儿。手心是热的，有一点潮。"},{"t":"n","text":"「明天。」他说，「七点。图书馆三楼。」"},{"t":"n","text":"你说：「还有必要占座吗。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"luchen","text":"有。"},{"t":"n","text":"「为什么。」"},{"t":"c","id":"luchen","text":"习惯了。"},{"t":"n","text":"他补了一句：「而且，我怕你哪天不来了。」"},{"t":"n","text":"那天晚上他送你到宿舍楼下。"},{"t":"n","text":"走到门口，他忽然说：「你等我一下。」"},{"t":"n","text":"他转身跑回实验楼。四分钟后下来，手里拿着那本深蓝的旧笔记。"},{"t":"n","text":"他把书递给你。"},{"t":"c","id":"luchen","text":"这个，正式给你。"},{"t":"n","text":"你翻开扉页。你的名字写在最上面，下面压着两个被涂掉的名字。"},{"t":"n","text":"最下面多了一行新的字，是他的笔迹："},{"t":"n","text":"「以后，写在这里的人，是你。」"}]},{"t":"block","when":"low","steps":[{"t":"n","text":"你在楼下站到十一点。"},{"t":"n","text":"实验楼的灯一层层灭掉，最后只剩楼梯间。"},{"t":"n","text":"他出来的时候看见你，愣了一下。"},{"t":"c","id":"luchen","text":"你在这干嘛。"},{"t":"n","text":"你说，路过。"},{"t":"n","text":"他看了你两秒。"},{"t":"c","id":"luchen","text":"哦。"},{"t":"n","text":"你们一起走到校门口。他往左，你往右。"},{"t":"n","text":"分开前，他从口袋里摸出一样东西，塞给你。"},{"t":"n","text":"是一张折叠的纸。你打开，是一张手绘的地图。"},{"t":"n","text":"上面画着北边那所学校的平面图。图书馆被圈了出来，旁边写着「三楼，靠窗」。"},{"t":"n","text":"地图的右下角写着一行小字：「寒假，我回来。」"},{"t":"n","text":"你抬头。他已经走远了。"},{"t":"n","text":"那天晚上，你把那张地图摊在桌上，看了很久。"},{"t":"n","text":"地图上有一条线，从他学校画到你学校。线是直的。"},{"t":"n","text":"直线上写着两个字：「四小时。」"}]},{"t":"block","when":"hasFlag2","minAff":null,"steps":[{"t":"n","text":"六月的晚上，风是热的。实验楼的灯还亮着。"},{"t":"n","text":"你们已经在一起三个星期。这三个星期里，你们吵了一次架。"},{"t":"n","text":"起因很小。他替你改了一份申请材料，没有告诉你。"},{"t":"n","text":"你发现的时候，已经交上去了。"},{"t":"n","text":"「你为什么不问。」你说。"},{"t":"n","text":"他站在台阶上，比你高半级。"},{"t":"c","id":"luchen","text":"我以为你要。"},{"t":"n","text":"「你以为。」"},{"t":"n","text":"他沉默了几秒。"},{"t":"c","id":"luchen","text":"我做错了。"},{"t":"n","text":"他说得很快，像把一句话念完。"},{"t":"n","text":"你忽然更生气了。你说：「你连为什么错都不知道。」"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"我知道。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"我把你当成我自己了。"},{"t":"n","text":"他说：「我以后问你。」"},{"t":"n","text":"他补了一句：「每一件。」"}]}],"id":"luchen_14"},{"no":15,"title":"站台","week":41,"bg":"station_dusk","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"站台上人很多。行李箱的轮子在地上滚，声音一片。"},{"t":"n","text":"他比你早走三天。北边的学校九月开学，他要提前过去做项目。"},{"t":"n","text":"他的行李很少：一个背包，一个纸箱。纸箱上写着「书」。"},{"t":"n","text":"你把一袋东西塞给他。是路上吃的，两瓶水，四个面包。"},{"t":"n","text":"他看了一眼，说：「太多了。」"},{"t":"n","text":"你说：「路上饿。」"},{"t":"n","text":"他没有再推。"},{"t":"n","text":"广播报了一次车次。还有十五分钟。"},{"t":"n","text":"他把纸箱放在地上，坐下来。"},{"t":"c","id":"luchen","text":"坐。"},{"t":"n","text":"你也坐下。站台的水泥地是凉的。"},{"t":"n","text":"「那边有宿舍。」他说，「两人间。有窗。」"},{"t":"n","text":"你说：「挺好。」"},{"t":"n","text":"「食堂一般。」"},{"t":"n","text":"「嗯。」"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"你要是来，我带你去后门那家面馆。"},{"t":"n","text":"你说：「你才去几天，就知道后门有面馆。」"},{"t":"c","id":"luchen","text":"查的。"},{"t":"n","text":"你笑了。他没有笑，但他也没有躲。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我会去看你」","hint":"把话说明白 · 也把责任担上","eff":{"aff":6.0,"happy":4.0,"stress":2.0,"lover":true},"reply":[{"t":"n","text":"你说：「十月，我去看你。」"},{"t":"n","text":"他转过头。"},{"t":"c","id":"luchen","text":"十月有课。"},{"t":"n","text":"「我翘。」"},{"t":"n","text":"他看了你三秒。"},{"t":"c","id":"luchen","text":"车票多少钱。"},{"t":"n","text":"你说：「你别管。」"},{"t":"n","text":"他把手伸过来，摊开。"},{"t":"c","id":"luchen","text":"一人一半。"},{"t":"n","text":"你说不用。"},{"t":"n","text":"他没有收手。"},{"t":"c","id":"luchen","text":"一人一半。这样才是你来看我，不是你来给我送东西。"},{"t":"n","text":"你把钱放在他手心里。他数了一遍，把一半塞回你口袋。"}]},{"label":"B","text":"说「到了给我消息」","hint":"先走到这一步 · 稳一点","eff":{"aff":3.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你说：「到了给我消息。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"「每天。」"},{"t":"n","text":"他看了你一眼。"},{"t":"c","id":"luchen","text":"每天。"},{"t":"n","text":"广播又报了一次。他站起来，把纸箱抱起来。"},{"t":"n","text":"抱起来的时候，纸箱底裂了一道。"},{"t":"n","text":"你伸手托住。"},{"t":"n","text":"你们一人托一边，把箱子搬到车门口。"}]},{"label":"C","text":"什么也没说，帮他把箱子搬上车","hint":"不承诺 · 只做眼前的事","eff":{"aff":4.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你没有说话。你抱起纸箱，往车门走。"},{"t":"n","text":"他跟在你后面。"},{"t":"n","text":"箱子很沉。你走到车门口，手臂发酸。"},{"t":"n","text":"他从后面伸手，托住箱底。"},{"t":"n","text":"两个人一起把箱子递上去。"},{"t":"n","text":"列车员说：「快点，要开了。」"},{"t":"n","text":"他上车。站在车门里面，隔着玻璃看你。"},{"t":"n","text":"玻璃上有水汽。他抬手擦了一下。"}]}]},{"t":"n","text":"列车开动的时候，他站在车门边。"},{"t":"n","text":"他没有挥手。他只是把手贴在玻璃上。"},{"t":"n","text":"你也把手贴上去。隔着一层玻璃，两只手的位置差了一点。"},{"t":"n","text":"车走了。站台上的人慢慢散掉。"},{"t":"n","text":"你低头，看见地上有一张纸。"},{"t":"n","text":"是他那张手绘地图，从口袋里掉出来的。"},{"t":"n","text":"你捡起来。地图背面多了一行新的字："},{"t":"n","text":"「十月，别翘课。我回来。」"},{"t":"n","text":"字写得很轻，像怕被人看见。"},{"t":"n","text":"你回到宿舍，把那张地图钉在墙上。"},{"t":"n","text":"室友问：「这谁画的。」"},{"t":"n","text":"你说：「同学。」"},{"t":"n","text":"室友凑近看了一眼：「画得挺仔细。连图书馆的窗都标了。」"},{"t":"n","text":"你说：「他做事就这样。」"},{"t":"n","text":"晚上十一点，手机亮了。是他。"},{"t":"n","text":"「到了。」"},{"t":"n","text":"隔了两分钟，又来一条。"},{"t":"n","text":"「宿舍有窗。能看见一棵树。」"},{"t":"n","text":"你回：「什么树。」"},{"t":"n","text":"他回：「不知道。回头拍给你。」"},{"t":"n","text":"那张照片是三天后来的。拍得很正，树占了画面中间。树下有一条长椅，没有人坐。"},{"t":"n","text":"照片背面没有字。你把它和地图钉在了一起。"},{"t":"n","text":"十月你没有去。十一月，他也没有回来。"},{"t":"n","text":"十二月，他寄来一本书。书里夹着一张车票，是他回来那次没用的。"},{"t":"n","text":"票面上的日期是十月三日。已经过期了。"},{"t":"n","text":"你把票夹进书里，放在床头。"},{"t":"n","text":"那天夜里你醒了一次。窗外的路灯亮着，像站台上那盏。"}],"id":"luchen_15"}]},{"id":"ch3","title":"第三章 · 职场","scenes":[{"no":16,"title":"会场外的台阶","week":45,"bg":"cafe","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"消息是下午来的。一个很久没亮过的头像。"},{"t":"n","text":"「我在你们这儿。三天。会场在城西。」"},{"t":"n","text":"你回：「什么时候有空。」"},{"t":"n","text":"他回：「晚上九点以后。」"},{"t":"n","text":"九点四十，你到那家快捷酒店楼下。旁边是一家便利店，灯很白。"},{"t":"n","text":"他站在门口的台阶上，穿着一件深灰的薄外套，里面还是白衬衫。"},{"t":"n","text":"他瘦了。下颌线比大学时更利。"},{"t":"n","text":"看见你，他没有立刻走过来。他先把手里的东西放进包里，然后才下台阶。"},{"t":"c","id":"luchen","text":"你比照片上瘦。"},{"t":"n","text":"你说：「你也是。」"},{"t":"n","text":"他「嗯」了一声。"},{"t":"n","text":"便利店的自动门开开合合。里面在放一首很老的歌。"},{"t":"n","text":"「吃了吗。」他问。"},{"t":"n","text":"你说没有。"},{"t":"n","text":"他转身进店，两分钟后出来，手里两个关东煮的纸杯。"},{"t":"n","text":"他把其中一个递给你。杯子上热气很足，糊了一下他的眼镜——他没有眼镜。"},{"t":"n","text":"你们站在台阶上吃。萝卜煮得太久，一夹就散。"},{"t":"n","text":"「课题做到哪一步了。」你问。"},{"t":"c","id":"luchen","text":"第三步。卡了两个月。"},{"t":"n","text":"「两个月？」"},{"t":"c","id":"luchen","text":"嗯。数据不对。"},{"t":"n","text":"他把竹签放下。"},{"t":"c","id":"luchen","text":"可能是方向错了。也可能是我算错了。"},{"t":"n","text":"你说：「你以前不会算错。」"},{"t":"n","text":"他看了你一眼。"},{"t":"c","id":"luchen","text":"以前是考试。"},{"t":"n","text":"他说完，低头继续吃。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"带他去吃一碗热面","hint":"不站在门口 · 坐下来","eff":{"aff":6.0,"happy":4.0,"stress":-3.0,"fin":-2.0},"reply":[{"t":"n","text":"你说：「这个吃不饱。前面有家面馆。」"},{"t":"n","text":"他看了一眼手里的纸杯，又看了看你。"},{"t":"c","id":"luchen","text":"行。"},{"t":"n","text":"面馆很小，六张桌子，墙上贴着价目表。老板认识你，问「还是老样子」。"},{"t":"n","text":"你点了两碗。他要了一碗清汤的，不加辣。"},{"t":"n","text":"面上来，他没有马上动筷子。他看着碗，看了一会儿。"},{"t":"c","id":"luchen","text":"这边面是甜的。"},{"t":"n","text":"你说：「你可以加醋。」"},{"t":"n","text":"他加了两勺醋，吃了一口。"},{"t":"c","id":"luchen","text":"还是甜的。"},{"t":"n","text":"但他把整碗吃完了，汤也喝了。"},{"t":"n","text":"结账的时候他抢着付。你把他的手按回去。"},{"t":"n","text":"他的手很凉。你说：「到我这儿了。」"},{"t":"n","text":"他愣了一下，把手收回去。"},{"t":"c","id":"luchen","text":"哦。"},{"t":"n","text":"走出面馆，他忽然说：「刚才那句，再说一遍。」"}]},{"label":"B","text":"陪他在便利店门口坐到打烊","hint":"不安排 · 就这样站着","eff":{"aff":4.0,"eq":2.0,"happy":3.0},"reply":[{"t":"n","text":"你们没有走。台阶是水泥的，坐着有点凉。"},{"t":"n","text":"他把外套脱下来，垫在你那半边。"},{"t":"n","text":"你说：「你自己不冷？」"},{"t":"c","id":"luchen","text":"我习惯了。"},{"t":"n","text":"便利店的店员出来倒垃圾，看了你们一眼。"},{"t":"n","text":"十一点，店里开始收拾。灯关了一半。"},{"t":"n","text":"他说：「你明天上班。」"},{"t":"n","text":"你说：「八点半。」"},{"t":"n","text":"他站起来，把外套穿上。"},{"t":"c","id":"luchen","text":"回去吧。"},{"t":"n","text":"走了几步，他停下来。"},{"t":"c","id":"luchen","text":"这三天，我每天晚上九点以后都在。"},{"t":"n","text":"他没有说「你来」。但意思很清楚。"}]},{"label":"C","text":"说你明天要上班，先走","hint":"先顾自己 · 也说得过去","eff":{"aff":1.0,"stress":-2.0,"happy":-1.0},"reply":[{"t":"n","text":"你看了一眼时间，说：「我明天要早起。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"嗯。你回去吧。"},{"t":"n","text":"你把没吃完的纸杯扔进垃圾桶。"},{"t":"n","text":"走到路口，你回头。他还站在台阶上。"},{"t":"n","text":"看见你回头，他抬起手，很轻地摆了一下。"},{"t":"n","text":"第二天晚上九点，你没有去。十点，手机亮了。"},{"t":"n","text":"「今天的会开完了。明天也是九点。」"}]}]},{"t":"n","text":"他送你到地铁口。地铁已经停了，你打算打车。"},{"t":"n","text":"他陪你站在路边等。风很大，他把外套的拉链拉到最上面。"},{"t":"n","text":"车来的时候，他忽然说：「你住几楼。」"},{"t":"n","text":"你说：「六楼。靠马路那面。」"},{"t":"n","text":"他点头，记下了。"},{"t":"n","text":"车开出去一段，你回头看。他还站在路边，抬头看着某个方向。"},{"t":"n","text":"你不知道他在看什么。你们隔了两条街。"},{"t":"n","text":"到家以后，你打开窗。楼下路边站着一个人，很小。"},{"t":"n","text":"你开了灯。他抬起手，摆了一下。"},{"t":"n","text":"你把灯关了，又打开。"},{"t":"n","text":"他转身走了。"}],"id":"luchen_16"},{"no":17,"title":"夜车","week":49,"bg":"station_dusk","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"凌晨一点的候车厅，人不多。暖气开得很足，椅子是硬的。"},{"t":"n","text":"他坐在第三排，脚边一个背包。他穿着那天那件深灰外套。"},{"t":"n","text":"他父亲脑梗，送进了县医院。他从北边飞回来，在你这个城市转车。"},{"t":"n","text":"中间有四个小时的等待。"},{"t":"n","text":"你到的时候，他正低头看手机。屏幕上是检验单的照片。"},{"t":"n","text":"他抬头，看见你。"},{"t":"c","id":"luchen","text":"你怎么来了。"},{"t":"n","text":"你说：「你说你在这儿。」"},{"t":"n","text":"他把手机按灭。"},{"t":"c","id":"luchen","text":"不用来。"},{"t":"n","text":"你没有走。你在旁边坐下。"},{"t":"n","text":"候车厅的广播在报一个晚点的车次。声音很闷。"},{"t":"n","text":"过了很久，他开口。"},{"t":"c","id":"luchen","text":"他退休了。去年。"},{"t":"n","text":"你说：「我知道。」"},{"t":"c","id":"luchen","text":"他把墙上的纸都撕了。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"我回家的时候，墙上只剩胶印。"},{"t":"n","text":"你想象那面墙。七张复印件，边角对得很齐。"},{"t":"n","text":"「他为什么撕。」"},{"t":"c","id":"luchen","text":"他说，教了一辈子，最后也就这样。"},{"t":"n","text":"他说这句话的时候，声音没有变。他只是把手放在膝盖上，手指交叠。"},{"t":"n","text":"「他现在怎么样。」"},{"t":"c","id":"luchen","text":"说话不利索。右边的手抬不起来。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"luchen","text":"他今天早上，跟我说的第一句话是『你回来干什么』。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"陪他坐这趟夜车","hint":"跟他一起走 · 不问他需要","eff":{"aff":8.0,"happy":5.0,"stress":3.0},"reply":[{"t":"n","text":"你去窗口买了一张同车次的票。"},{"t":"n","text":"回来的时候，他看见你手里的票，站了起来。"},{"t":"c","id":"luchen","text":"你不用。"},{"t":"n","text":"你说：「我知道我不用。」"},{"t":"n","text":"他看了你很久。"},{"t":"n","text":"候车厅的灯管有一根在闪。"},{"t":"c","id":"luchen","text":"明天你要上班。"},{"t":"n","text":"你说：「我请假了。」"},{"t":"n","text":"他没有再说什么。他坐回去，把背包往旁边挪了挪，给你让出位置。"},{"t":"n","text":"上车以后，车厢很空。你们坐在一起，谁也没说话。"},{"t":"n","text":"过了半小时，他忽然把头靠在椅背上，闭上眼睛。"},{"t":"n","text":"他的手还放在膝盖上，没有松开。"},{"t":"n","text":"你把外套盖在他身上。他没有动。"}]},{"label":"B","text":"送他上车，在这边等消息","hint":"留在这里 · 也是一种支持","eff":{"aff":4.0,"eq":3.0,"happy":1.0},"reply":[{"t":"n","text":"你说：「我送你上车。到了给我消息。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"好。"},{"t":"n","text":"检票的时候，他走了两步，回头。"},{"t":"c","id":"luchen","text":"你回去吧。太晚了。"},{"t":"n","text":"你说：「我看着你进去。」"},{"t":"n","text":"他站了一会儿，转身进去。"},{"t":"n","text":"玻璃门后面的背影很直，走得不快。"},{"t":"n","text":"凌晨三点，手机亮了。"},{"t":"n","text":"「到了。他睡了。」"},{"t":"n","text":"过了两分钟，又来一条。"},{"t":"n","text":"「谢谢你今天来。」"}]},{"label":"C","text":"说「你爸会好的」","hint":"想安慰 · 但说错了","eff":{"aff":-3.0,"happy":-2.0,"eq":1.0},"reply":[{"t":"n","text":"你说：「别担心，你爸会好的。」"},{"t":"n","text":"他抬起头，看了你一眼。"},{"t":"n","text":"那一眼里没有责怪。他只是把视线移回手机上。"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"广播又报了一次车次。"},{"t":"n","text":"他站起来，背上包。"},{"t":"c","id":"luchen","text":"我该进去了。"},{"t":"n","text":"你跟着站起来。他走了两步，停下。"},{"t":"c","id":"luchen","text":"你说的那句话，我妈也说。"},{"t":"n","text":"他转身，往检票口走。"},{"t":"n","text":"检票口的灯很亮。他走进去，没有回头。"}]}]},{"t":"n","text":"三天后，他发来一张照片。"},{"t":"n","text":"是医院的走廊。他父亲坐在轮椅上，穿着病号服，右手搭在扶手上。"},{"t":"n","text":"照片拍得很正。他的习惯。"},{"t":"n","text":"下面一行字：「能抬手了。」"},{"t":"n","text":"你回了一个「好」字。"},{"t":"n","text":"过了很久，他又发来一条。"},{"t":"n","text":"「他问我，那天在车站的人是谁。」"},{"t":"n","text":"你问：「你怎么说的。」"},{"t":"n","text":"他回：「同学。」"},{"t":"n","text":"再过了十分钟。"},{"t":"n","text":"「他说，同学不会半夜来。」"},{"t":"n","text":"你在手机上打了一行字，又删掉。"},{"t":"n","text":"第二天，你收到一个快递。里面是一个保温杯，附了一张纸条。"},{"t":"n","text":"「车站太冷。这个保温。」"},{"t":"n","text":"纸条上没有署名。快递单上的寄件人写的是「陆」。"},{"t":"n","text":"你把保温杯洗干净，放在办公桌上。同事问哪里买的。"},{"t":"n","text":"你说：「别人给的。」"},{"t":"n","text":"那个杯子你用了很多年。杯底的漆掉了一块。"}],"id":"luchen_17"},{"no":18,"title":"学术会议","week":53,"bg":"office_day","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"学术会议在城西的酒店。大厅里全是挂着参会牌的人。"},{"t":"n","text":"你在大厅看见他，胸前挂着牌子，头发比大学时短了。"},{"t":"n","text":"他站在一块展板前面，看一张图。他没有立刻看见你。"},{"t":"n","text":"你走过去。他的目光从展板上移开，落在你身上。"},{"t":"n","text":"他停了半秒。"},{"t":"c","id":"luchen","text":"好久不见。"},{"t":"n","text":"你说：「好久不见。」"},{"t":"n","text":"他把牌子摘下来，捏在手里。"},{"t":"c","id":"luchen","text":"喝杯咖啡？"},{"t":"n","text":"酒店的咖啡厅在二楼。人不多，靠窗的位置空着。"},{"t":"n","text":"你们坐到打烊。中间说了很多话，都是工作。"},{"t":"n","text":"他说他的课题，说数据，说一个做了两年没有结果的模型。"},{"t":"n","text":"你说你的项目，说甲方，说一个改了十一版的方案。"},{"t":"n","text":"说完，两个人都沉默了。"},{"t":"n","text":"服务员来收杯子。他看了一眼时间。"},{"t":"c","id":"luchen","text":"下个月，我去另一个城市。"},{"t":"n","text":"你说：「调动？」"},{"t":"c","id":"luchen","text":"不是。有个位置。"},{"t":"n","text":"他把杯子放下。"},{"t":"c","id":"luchen","text":"做研究。三年。"},{"t":"n","text":"你说：「那……恭喜。」"},{"t":"n","text":"他看了你很久。"},{"t":"c","id":"luchen","text":"当年在实验楼门口，你是不是有话要说。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「你去。我们把这件事算清楚」","hint":"不阻拦 · 也不装作没事","eff":{"aff":6.0,"eq":4.0,"happy":2.0},"reply":[{"t":"n","text":"你说：「你去。但我们把这件事算清楚。」"},{"t":"n","text":"他从包里拿出笔。"},{"t":"n","text":"你们在那张纸的背面写了三条：多久见一次，谁先说话，吵架不许过夜。"},{"t":"n","text":"写完，他看了很久。"},{"t":"c","id":"luchen","text":"第三条，我做不到。"},{"t":"n","text":"你说：「那就改成，第二天早上必须说话。」"},{"t":"n","text":"他划掉，重新写。"},{"t":"c","id":"luchen","text":"行。"}]},{"label":"B","text":"说「你想去就去」","hint":"把选择还给他 · 话咽回去","eff":{"aff":2.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"你说：「你想去就去。」"},{"t":"n","text":"他点头，把纸收起来。"},{"t":"c","id":"luchen","text":"好。"},{"t":"n","text":"他收得很快。快到你来不及补一句别的。"},{"t":"n","text":"咖啡凉了。他一口没喝。"},{"t":"n","text":"走出酒店，他说：「我送你。」"},{"t":"n","text":"你说不用。"},{"t":"n","text":"他站在原地。"},{"t":"c","id":"luchen","text":"你刚才那句话，我不太喜欢。"}]},{"label":"C","text":"说「我跟你一起」","hint":"放弃这边 · 换一个开始","eff":{"aff":4.0,"happy":4.0,"stress":6.0,"fin":-4.0},"reply":[{"t":"n","text":"你说：「我跟你一起。」"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"你的工作。"},{"t":"n","text":"你说：「可以再找。」"},{"t":"n","text":"他没有立刻说话。他把那张纸翻过来，看了一会儿。"},{"t":"c","id":"luchen","text":"我不希望你为我辞掉什么。"},{"t":"n","text":"你说：「不是为你。」"},{"t":"n","text":"他看了你很久。"},{"t":"c","id":"luchen","text":"那你先去看一次。看完了再决定。"},{"t":"n","text":"他把笔递给你。"},{"t":"c","id":"luchen","text":"写下来。什么时候去。"}]}]},{"t":"block","when":"backfill2","steps":[{"t":"n","text":"他握着你的手，坐了一会儿。"},{"t":"n","text":"打烊的灯亮了，服务员在擦桌子。"},{"t":"n","text":"他站起来，说：「走。」"},{"t":"n","text":"你们走出酒店。街上很空，路灯把影子拉得很长。"},{"t":"n","text":"他说：「下个月我走。」"},{"t":"n","text":"你说：「我知道。」"},{"t":"n","text":"他停下脚步。"},{"t":"c","id":"luchen","text":"你要不要，跟我一起去看一次那个城市。"},{"t":"n","text":"他补了一句：「不是搬过去。就是去看看。」"},{"t":"n","text":"他说这句话的时候，没有看你。"}]},{"t":"block","when":"hasFlag2","minAff":null,"steps":[{"t":"n","text":"会议在城西的酒店。你们已经异地两年。"},{"t":"n","text":"两年里，视频从每天一次，变成三天一次，再变成「周末吧」。"},{"t":"n","text":"他站在展板前面。看见你，他把牌子摘下来。"},{"t":"c","id":"luchen","text":"你来了。"},{"t":"n","text":"你说：「你让我来。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"有件事，我想先跟你说，不是先决定。"},{"t":"n","text":"你们在咖啡厅坐下。他把一张纸推过来。"},{"t":"n","text":"是一个职位的说明。另一个城市，三年。"},{"t":"c","id":"luchen","text":"我想去。"},{"t":"n","text":"他说完，看着你。"},{"t":"c","id":"luchen","text":"但我先问你。"}]}],"id":"luchen_18"},{"no":19,"title":"他要走的那一年","week":55,"bg":"bedroom_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"他要走的那个月，城市热得反常。"},{"t":"n","text":"你的出租屋在七楼，没有电梯。他上来的时候，衬衫后背湿了一片。"},{"t":"n","text":"他手里拎着一个袋子。里面是两盒冰淇淋，已经开始化了。"},{"t":"c","id":"luchen","text":"路上买的。"},{"t":"n","text":"你说：「你不吃冰的。」"},{"t":"n","text":"他把袋子放在桌上。"},{"t":"c","id":"luchen","text":"你吃。"},{"t":"n","text":"你们坐在地板上吃。风扇转过来，纸盒的边角被吹起来。"},{"t":"n","text":"吃到一半，他说：「手续办完了。」"},{"t":"n","text":"你说：「什么时候走。」"},{"t":"c","id":"luchen","text":"月底。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"三年。"},{"t":"n","text":"你说：「你说过了。」"},{"t":"n","text":"他把勺子放下。"},{"t":"c","id":"luchen","text":"我在想一件事。"},{"t":"n","text":"「什么。」"},{"t":"n","text":"他看着地板。"},{"t":"c","id":"luchen","text":"我是不是，一直在往前跑。"},{"t":"n","text":"你说：「你不是喜欢吗。」"},{"t":"c","id":"luchen","text":"喜欢。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"但我不确定，我跑的方向，是不是我自己选的。"},{"t":"c","id":"luchen","text":"我爸选了一次。他选对了，也没选对。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「你去。我等你」","hint":"把话给足 · 也把难处担下","eff":{"aff":7.0,"happy":4.0,"stress":3.0},"reply":[{"t":"n","text":"你说：「你去。我等你。」"},{"t":"n","text":"他抬起头，看了你很久。"},{"t":"c","id":"luchen","text":"三年。"},{"t":"n","text":"「我知道。」"},{"t":"c","id":"luchen","text":"中间可能回不来。"},{"t":"n","text":"「我知道。」"},{"t":"n","text":"他把手撑在地板上，低下头。"},{"t":"n","text":"过了很久，他说：「你别等。」"},{"t":"n","text":"你说：「为什么。」"},{"t":"c","id":"luchen","text":"因为我不想，你的人生里有一段是空的。"},{"t":"n","text":"你说：「那是我的事。」"},{"t":"n","text":"他抬起头。眼睛有一点红。"},{"t":"c","id":"luchen","text":"那我就不说谢谢了。"},{"t":"n","text":"他说完，伸手把你拉过去。"},{"t":"n","text":"他的肩膀很硬，抱得也不太会。手放在你背上，停了一下，才慢慢收紧。"}]},{"label":"B","text":"说「我希望你留下」","hint":"把真话说出来 · 决定权在他","eff":{"aff":5.0,"happy":2.0,"stress":4.0},"reply":[{"t":"n","text":"你说：「我希望你留下。」"},{"t":"n","text":"他没有立刻回答。"},{"t":"n","text":"风扇转了一圈，转回来。"},{"t":"c","id":"luchen","text":"我知道。"},{"t":"n","text":"你说：「但这是你的事。我不替你决定。」"},{"t":"n","text":"他点头。点得很慢。"},{"t":"c","id":"luchen","text":"谢谢你说出来。"},{"t":"n","text":"他把冰淇淋盒子收起来，扔进垃圾桶。"},{"t":"n","text":"回来的时候，他站在窗边。"},{"t":"c","id":"luchen","text":"如果我留下，我会一直想那个地方。"},{"t":"n","text":"你说：「我知道。」"},{"t":"c","id":"luchen","text":"如果我走了，我会一直想这里。"},{"t":"n","text":"他转过身。"},{"t":"c","id":"luchen","text":"你告诉我，哪一个更像我。"}]},{"label":"C","text":"说「我跟你一起走」","hint":"放弃这边 · 换一个开始","eff":{"aff":3.0,"happy":5.0,"stress":5.0,"fin":-5.0},"reply":[{"t":"n","text":"你说：「我跟你一起走。」"},{"t":"n","text":"他把手里的盒子放下。"},{"t":"c","id":"luchen","text":"你的工作。"},{"t":"n","text":"「可以再找。」"},{"t":"c","id":"luchen","text":"你的朋友。你的房子。"},{"t":"n","text":"「都可以再找。」"},{"t":"n","text":"他沉默了很久。"},{"t":"c","id":"luchen","text":"我不接受。"},{"t":"n","text":"你说：「为什么。」"},{"t":"n","text":"他站起来，走到窗边。"},{"t":"c","id":"luchen","text":"因为我不想，以后你后悔的时候，怪的是我。"},{"t":"n","text":"他转过身。"},{"t":"c","id":"luchen","text":"你要去，是因为你自己想去。不是因为我要走。"},{"t":"n","text":"他说完，看着你。"},{"t":"c","id":"luchen","text":"你想去吗。"}]}]},{"t":"n","text":"十一点，他说要走。"},{"t":"n","text":"你送他到楼下。街上没什么人，烧烤摊在收摊，铁架子拖在地上响。"},{"t":"n","text":"你们走到天桥上。桥下的车灯一排一排过去。"},{"t":"n","text":"他扶着栏杆，站了一会儿。"},{"t":"c","id":"luchen","text":"我小时候，我爸带我来过一次城里。"},{"t":"n","text":"你说：「干嘛。」"},{"t":"c","id":"luchen","text":"看一个学校。他说，以后你要考到这里。"},{"t":"n","text":"他低下头，看着桥下。"},{"t":"c","id":"luchen","text":"我那时候觉得，那条路是直的。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"现在不觉得了。"},{"t":"n","text":"风把他的头发吹起来一点。"},{"t":"c","id":"luchen","text":"但我想走走看。"},{"t":"n","text":"他走的时候，你送到楼下。"},{"t":"n","text":"他背着包，站在路灯底下，影子被拉得很长。"},{"t":"n","text":"「有一件事。」他说。"},{"t":"n","text":"「什么。」"},{"t":"n","text":"他看着地面。"},{"t":"c","id":"luchen","text":"我这些年，赢过很多次。"},{"t":"n","text":"你等他说下去。"},{"t":"c","id":"luchen","text":"只有跟你比的时候，我会算错。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"我不知道这算什么。"},{"t":"n","text":"你说：「算好事。」"},{"t":"n","text":"他看了你很久，然后点头。"},{"t":"c","id":"luchen","text":"那我记下了。"},{"t":"n","text":"他走到路口，抬手看了一眼手腕。"},{"t":"n","text":"那个动作你看了很多年。你知道他要把表往上推一下，才看得清。"},{"t":"n","text":"你也知道，他其实知道现在几点。"}],"id":"luchen_19"},{"no":20,"title":"送别","week":58,"bg":"airport","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"机场的出发层，玻璃很大，光很白。"},{"t":"n","text":"他的行李还是很少：一个背包，一个纸箱。纸箱上写着「书」。"},{"t":"n","text":"这一次纸箱没有裂。他用胶带在底部缠了两圈。"},{"t":"n","text":"值机柜台前面排了很长的队。他排在中间，你站在队外面。"},{"t":"n","text":"轮到他的时候，他把箱子放上去。秤上显示二十三公斤。"},{"t":"n","text":"工作人员说：「超了两公斤。」"},{"t":"n","text":"他打开箱子，把两本书拿出来，抱在怀里。"},{"t":"n","text":"你看见那两本书的书脊。一本是旧的，深蓝，用透明胶粘过。"},{"t":"n","text":"他抱着书走回来。"},{"t":"c","id":"luchen","text":"这个不能托运。"},{"t":"n","text":"你说：「你带它干什么。」"},{"t":"n","text":"他把书放进背包。"},{"t":"c","id":"luchen","text":"习惯了。"},{"t":"n","text":"离登机还有四十分钟。你们在落地窗前面站着。"},{"t":"n","text":"窗外停着几架飞机，有一架在缓缓后退。"},{"t":"n","text":"他忽然说：「把手伸出来。」"},{"t":"n","text":"你伸出手。"},{"t":"n","text":"他把左手腕上的表摘下来，放在你手心。"},{"t":"n","text":"深蓝尼龙表带，表盘上有一道划痕。表还是走的。"},{"t":"c","id":"luchen","text":"这个给你。"},{"t":"n","text":"你说：「这是你爸给你的。」"},{"t":"c","id":"luchen","text":"嗯。"},{"t":"n","text":"他把表带扣好，在你手腕上。扣到最里面一格，还是有一点松。"},{"t":"c","id":"luchen","text":"松一点好。勒着不舒服。"},{"t":"n","text":"他抬起你的手，看了一眼表盘。"},{"t":"c","id":"luchen","text":"它慢三分钟。"},{"t":"n","text":"你说：「我知道。」"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"你知道？"},{"t":"n","text":"你说：「初中就知道了。」"},{"t":"n","text":"他愣住了。"},{"t":"n","text":"然后他笑了。这次笑得很明显，眼睛也弯了。"},{"t":"c","id":"luchen","text":"那你知道，我为什么一直不修吗。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我等你」","hint":"把话说满 · 也把日子过好","eff":{"aff":8.0,"happy":6.0,"stress":2.0},"reply":[{"t":"n","text":"你说：「我等你。」"},{"t":"n","text":"他低下头，看着你手腕上的表。"},{"t":"c","id":"luchen","text":"三年。"},{"t":"n","text":"「三年。」"},{"t":"n","text":"他抬起手，像是想碰一下你的脸，抬到一半又放下。"},{"t":"n","text":"最后他只是把手指放在你的手背上，按了一下。"},{"t":"c","id":"luchen","text":"那我走快点。"}]},{"label":"B","text":"说「别等我」","hint":"把门留一条缝 · 也放过彼此","eff":{"aff":2.0,"happy":-4.0,"stress":2.0},"reply":[{"t":"n","text":"你说：「别等我。」"},{"t":"n","text":"他抬起头。"},{"t":"n","text":"你说：「三年太长了。我们都别把自己钉在这儿。」"},{"t":"n","text":"他看了你很久。"},{"t":"c","id":"luchen","text":"好。"},{"t":"n","text":"他把手收回去。"},{"t":"c","id":"luchen","text":"那这个表……"},{"t":"n","text":"你说：「表我留着。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"luchen","text":"行。"},{"t":"n","text":"广播开始报登机。他把背包背上。"}]},{"label":"C","text":"什么也不说，抱他一下","hint":"不承诺 · 只留一个动作","eff":{"aff":5.0,"happy":3.0,"stress":1.0},"reply":[{"t":"n","text":"你没有说话。"},{"t":"n","text":"你上前一步，抱住他。"},{"t":"n","text":"他站着没有动。过了两秒，他的手才抬起来。"},{"t":"n","text":"他抱得不太会。手臂收得很紧，人却离得有点远。"},{"t":"n","text":"你听见他的呼吸，就在耳边。"},{"t":"n","text":"很久，他说了一句。"},{"t":"c","id":"luchen","text":"我会回来。"},{"t":"n","text":"他说得很轻，像是说给自己听。"}]}]},{"t":"n","text":"广播第三次报登机。他该走了。"},{"t":"n","text":"他往安检口走。走到一半，他回头。"},{"t":"n","text":"「喂。」他喊了一声。"},{"t":"n","text":"你抬头。"},{"t":"n","text":"他站在人群里，个子比周围的人都高一点。"},{"t":"c","id":"luchen","text":"下一次，我先说。"},{"t":"n","text":"你说：「说什么。」"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"luchen","text":"所有。"},{"t":"n","text":"他转身，走进安检口。"},{"t":"n","text":"你站在原地，看着他过安检，拿行李，走进通道。"},{"t":"n","text":"他没有再回头。"},{"t":"n","text":"你低头看表。九点二十七。"},{"t":"n","text":"你的手机上是九点三十。"},{"t":"n","text":"你站在那里，把表盘对着光看了一会儿。"},{"t":"n","text":"表盘上的划痕在光里，很细，很长。"},{"t":"n","text":"你低头，把表带又扣紧了一格。"}],"id":"luchen_20","judgeAfter":true}]},{"id":"finale","title":"终章 · 三种结局","scenes":[{"no":21,"title":"两个不肯认输的人","week":60,"bg":"airport","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"三年。"},{"t":"n","text":"第一年，你们每天视频。有时候开着不说话，各做各的事。"},{"t":"n","text":"他那边是白天，你这边是夜里。屏幕的光照着你的脸，他在写数据，偶尔抬头看一眼。"},{"t":"n","text":"第二年，变成三天一次。第三年，他在赶一个项目，你在赶一个晋升。"},{"t":"n","text":"你们吵过两次架。一次因为他忘了你的生日，一次因为你没有告诉他你住院。"},{"t":"n","text":"第二次吵得比较凶。他在电话那头沉默了很久，说：「你不说，我怎么知道。」"},{"t":"n","text":"你说：「你也不说。」"},{"t":"n","text":"两个人在电话里沉默。"},{"t":"n","text":"最后他说：「那我们定个规矩。」"},{"t":"n","text":"「什么规矩。」"},{"t":"n","text":"「难受的时候，先说一句『我不太好』。」"},{"t":"n","text":"你说：「就这样？」"},{"t":"n","text":"他说：「就这样。剩下的，我来问。」"},{"t":"n","text":"三年后的九月，他回来了。航班晚点两个小时。"},{"t":"n","text":"你在大厅等了很久。出口的门开开合合，出来的人一拨又一拨。"},{"t":"n","text":"最后他出来。推着一个箱子，背包带子滑到一边。"},{"t":"n","text":"他瘦了一点，头发更短，白衬衫换成了深色。"},{"t":"n","text":"他看见你，停下脚步。"},{"t":"n","text":"没有拥抱，没有喊。他把箱子放下，走过来，站在你面前。"},{"t":"c","id":"luchen","text":"我回来了。"},{"t":"n","text":"你说：「嗯。」"},{"t":"n","text":"他看了你一会儿。"},{"t":"c","id":"luchen","text":"你瘦了。"},{"t":"n","text":"你说：「你也是。」"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"luchen","text":"我这次待很久。"},{"t":"n","text":"「多久。」"},{"t":"n","text":"他弯腰，把箱子拉起来。"},{"t":"c","id":"luchen","text":"不走了。"},{"t":"n","text":"后来你问过他一次。"},{"t":"n","text":"那天你们在收拾屋子，他把书从箱子里一本一本拿出来。"},{"t":"n","text":"你问：「你什么时候开始喜欢我的。」"},{"t":"n","text":"他想了很久。久到你以为他不会答。"},{"t":"c","id":"luchen","text":"你第一次赢我的时候。"},{"t":"n","text":"你说：「我从来没赢过你。」"},{"t":"n","text":"他把书放下。"},{"t":"c","id":"luchen","text":"你赢了。你自己不知道。"},{"t":"n","text":"「哪一次。」"},{"t":"n","text":"他看了你一眼。"},{"t":"c","id":"luchen","text":"初三。最后一题。"},{"t":"n","text":"你愣住了。"},{"t":"c","id":"luchen","text":"我那道题没做出来。回家以后，我做了三个小时。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"做出来的时候，我想的是，明天要告诉你。"},{"t":"n","text":"「然后呢。」"},{"t":"c","id":"luchen","text":"然后我就知道，完了。"},{"t":"n","text":"他说这话的时候，耳朵有一点红。"},{"t":"n","text":"求婚没有戒指。"},{"t":"n","text":"那天他约你去母校。图书馆三楼在装修，进不去。"},{"t":"n","text":"你们在楼下站着。他抬头看三楼那排窗。"},{"t":"n","text":"「第三个。」他说。"},{"t":"n","text":"你说：「我记得。」"},{"t":"n","text":"他从口袋里拿出一张纸。是那张过期的竞赛报名表，被压得很平，边缘用透明胶贴过。"},{"t":"n","text":"「这个，我要跟你换一样东西。」"},{"t":"n","text":"你问：「换什么。」"},{"t":"n","text":"他把纸递给你。"},{"t":"c","id":"luchen","text":"换你以后的时间。"},{"t":"n","text":"他说完，自己先皱了一下眉。"},{"t":"c","id":"luchen","text":"这句，我练了三天。还是不好。"},{"t":"n","text":"你笑了。"},{"t":"n","text":"你说：「行。」"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"行是什么意思。"},{"t":"n","text":"你说：「就是行。」"},{"t":"n","text":"他站在那里，手里还拿着那张纸，像是没反应过来。"},{"t":"n","text":"过了几秒，他把纸收好，很小心地折成三折，放回口袋。"},{"t":"c","id":"luchen","text":"那我记下了。"},{"t":"n","text":"婚礼在秋天。请的人不多。"},{"t":"n","text":"司仪让他讲两句。他拿着话筒，站了很久。"},{"t":"n","text":"台下开始有人笑。他也笑了一下，很短。"},{"t":"n","text":"然后他说："},{"t":"c","id":"luchen","text":"我输了。"},{"t":"n","text":"台下哄笑。有人吹口哨。"},{"t":"n","text":"他等笑声下去，补了一句。"},{"t":"c","id":"luchen","text":"我这辈子，只输给过一个人。输得心甘情愿。"},{"t":"n","text":"你站在他旁边，看见他的耳朵红了。"},{"t":"n","text":"他把话筒递回来，手有一点抖。"},{"t":"n","text":"你伸手，握住他的手。"},{"t":"n","text":"他的手心是热的。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把旧笔记留在书架上","hint":"留给下一个人","eff":{"happy":5.0},"reply":[{"t":"n","text":"他问为什么不收起来。你说：「够不着的地方，才会有人想拿。」"}]},{"label":"B","text":"收进抽屉，锁上","hint":"只留给你们两个","eff":{"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"他把钥匙递给你。你说：「你拿着。」他说：「那就放两把。」"}]}]}],"quality":{"high":["你们还是会为谁洗碗吵架。","每次吵完，他都会把碗洗了，然后说：「下次你洗。」","下次还是他洗。","他还是不太会说。你难受的时候，他先问一句「怎么了」，然后坐在旁边，等你开口。","有时候你什么也不说，他就一直坐着。","那本深蓝的旧笔记放在书架上。扉页有三个名字：两个被涂掉，一个是你。","有一年，他带的学生来家里吃饭。那个孩子看见那本书，问：「老师，这个能借我吗。」","他看了你一眼。","你说：「借。」","他补了一句：「看完要还。要写名字。」"],"mid":["日子过得很稳。","稳到你有时候会想，他是不是把经营感情也当成了一道题。","他记得所有的纪念日，会提前订餐厅，会在日历上标出来。","但他常常忘记问你今天开不开心。","你也没说。","有一年冬天，你加班到很晚。回家时他在客厅等你，桌上的菜热过两遍。","他说：「以后晚回来，发个消息。」","你说好。","那之后，你们都发消息。消息越来越短。","但饭还是热的。"],"low":["他记得所有的纪念日。","纪念日那天，他会提前下班，把桌子擦一遍，把花插好。","然后坐下来，问你：「最近怎么样。」","你说：「还好。」","他就点头，不再问。","你们像两个很懂礼貌的人，住在一个屋子里。","有一年，你生病住院。他请了假，每天来，坐在床边处理工作。","出院那天，他帮你拎东西，走在前面。","你跟在后面，忽然想叫他的名字。","叫了。","他回头，说：「怎么了。」","你说：「没事。」","他点头，继续往前走。"]},"id":"luchen_21","ending":"stay","endingName":"结局一 · 两个不肯认输的人"},{"no":22,"title":"我们都没输，只是没在一起","week":60,"bg":"office_day","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"他走了。"},{"t":"n","text":"第一年，邮件每周一封。他写得很长，写实验室的窗，写楼下的猫，写食堂的汤太咸。"},{"t":"n","text":"你回得也长。你写你的项目，写你搬了家，写楼下那家面馆关门了。"},{"t":"n","text":"第二年，每月一封。第三年，只有过年。"},{"t":"n","text":"过年的那封很短：「新年好。今年这边下雪了。」"},{"t":"n","text":"你回：「新年好。这边没下。」"},{"t":"n","text":"后来连这封也没有了。"},{"t":"n","text":"你偶尔在学术新闻里看见他的名字。照片上的他，和大学时没什么两样。"},{"t":"n","text":"还是白衬衫。还是不太笑。"},{"t":"n","text":"你把那篇报道看完了，看到最后一行，关掉页面。"},{"t":"n","text":"很多年后，你们在一次会议上重逢。"},{"t":"n","text":"会场在城南，是你熟悉的城市。他作为主讲人，站在台上。"},{"t":"n","text":"他讲得很快，条理清楚。台下有人提问，他一条一条答。"},{"t":"n","text":"散场以后，你在走廊上看见他。"},{"t":"n","text":"他也看见你。"},{"t":"n","text":"他走过来。走得比年轻时候慢一点。"},{"t":"c","id":"luchen","text":"好久不见。"},{"t":"n","text":"你说：「好久不见。」"},{"t":"n","text":"他的无名指上有一枚很素的戒指。"},{"t":"n","text":"你们在大厅的沙发上坐下。聊了半个小时。"},{"t":"n","text":"聊的都是工作。他的课题，你的项目，行业里那些来来去去的人。"},{"t":"n","text":"中间有两次沉默，都被他接住了。"},{"t":"n","text":"临走的时候，他站起来。"},{"t":"c","id":"luchen","text":"当年……"},{"t":"n","text":"他停住了。"},{"t":"n","text":"他看着你，看了很久。"},{"t":"n","text":"然后他摇摇头。"},{"t":"c","id":"luchen","text":"算了。你保重。"},{"t":"n","text":"你说：「你也是。」"},{"t":"n","text":"他转身，走进人群。"},{"t":"n","text":"他没有回头。"},{"t":"n","text":"你站在原地，看见他的背影被大厅的灯照得很亮。"},{"t":"n","text":"走出酒店，天已经黑了。"},{"t":"n","text":"你在路边站了一会儿，掏出手机，翻到很多年前的一条草稿。"},{"t":"n","text":"那条消息一直没发出去。你也不知道为什么一直留着。"},{"t":"n","text":"你看了很久。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"发出去","hint":"迟了很多年 · 还是发","eff":{"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你按了发送。他回得很快：「我知道。」"},{"t":"n","text":"隔了很久，又来一条：「我也有一个。」"}]},{"label":"B","text":"删掉","hint":"把话咽回去 · 就这样","eff":{"happy":-1.0,"eq":1.0},"reply":[{"t":"n","text":"你按了删除。确认框弹出来，你按了确定。"}]},{"label":"C","text":"存成草稿","hint":"不发出 · 也不丢","eff":{"happy":1.0,"stress":1.0},"reply":[{"t":"n","text":"你把光标移到最前面，加了一句「其实那天」。然后又删掉。"},{"t":"n","text":"你把手机放回口袋，走进地铁口。"}]}]}],"quality":{"high":["你后来过得很好。","有一份做得下去的工作，有几个能半夜打电话的朋友。","你只是偶尔会想，如果那天你说出口了，会怎么样。","想完，你就去做别的事了。","有一年，你在旧书里翻出一张手绘地图。纸已经黄了。","地图上那条直线还在，旁边写着「四小时」。","你把它夹回书里。"],"mid":["你们偶尔在群里说话。","都是转发文章。行业新闻，招生简章，某个老师退休的消息。","你给他点过赞。他也给你点过。","有一年，他转发了一条关于睡眠的科普，配了一句：「你别熬夜。」","你回了一个「嗯」。","那之后，你们谁也没有再说话。"],"low":["你听说他结婚了。","消息是同学群里传出来的。有人发了一张照片，照片里他站在酒店门口，穿着一身深色西装。","你放大看了很久。","你替他高兴。","真的。","那天晚上你加班到很晚。回家的路上，你在便利店买了一瓶水。","结账的时候，你想起很多年前，有个人站在便利店门口，手里两个关东煮的纸杯。","你走出店门，站在台阶上，把水喝完。","台阶是水泥的。坐下来有一点凉。","你把水喝完，站起来，拍了拍裤子。","手机在口袋里震了一下。是同学群，有人发了一张合影。","照片里他站在最边上，比所有人都高一点。","你把照片放大，看了很久。","然后你退出来，回了一条：「都老了。」","发完，你往地铁口走。","走了十几步，你忽然停下来，回头看了一眼那家便利店。","灯很白。门口没有人。","你在原地站了一会儿，才想起来自己没吃晚饭。","你走到路对面，进了一家还在营业的面馆，点了一碗清汤面。","面上来，你加了两勺醋。"]},"id":"luchen_22","ending":"miss","endingName":"结局二 · 我们都没输，只是没在一起"},{"no":23,"title":"一辈子的对手","week":60,"bg":"livingroom_night","cast":["luchen"],"steps":[{"t":"cast","list":["luchen"],"focus":"luchen"},{"t":"n","text":"你们做了一辈子的朋友，也做了一辈子的对手。"},{"t":"n","text":"他出国三年，回来以后在城北的研究所工作。你在城南。"},{"t":"n","text":"中间隔着一座城，坐地铁要换两次。"},{"t":"n","text":"你们一个月见一次。有时候是他来，有时候是你去。"},{"t":"n","text":"见面主要是吃饭，然后各拿出一道题，或者一个方案，互相挑毛病。"},{"t":"n","text":"他挑得比年轻时候狠。"},{"t":"n","text":"「这里。」他用筷子点着纸，「你又在跳步。」"},{"t":"n","text":"你说：「这叫效率。」"},{"t":"n","text":"他把纸推回来。"},{"t":"c","id":"luchen","text":"这叫偷懒。"},{"t":"n","text":"你结婚那天，他当证婚人。"},{"t":"n","text":"他站在台上，穿了一身深色西装。领带系得比平时正。"},{"t":"n","text":"致辞的时候，他清了清嗓子。"},{"t":"c","id":"luchen","text":"我认识这个人很多年。"},{"t":"n","text":"台下有人笑。他等笑声下去。"},{"t":"c","id":"luchen","text":"我输过一次，记到现在。"},{"t":"n","text":"台下的人都笑了。你也笑。"},{"t":"n","text":"他继续说：「后来我发现，那次输了，也没什么。」"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"luchen","text":"因为输的那个人，一直还在。"},{"t":"n","text":"他说完，把稿子折起来，放进口袋。"},{"t":"n","text":"你站在旁边，忽然有一点想哭。"},{"t":"n","text":"后来你们各自成了家。"},{"t":"n","text":"他带的第一个学生来家里，是他带来的。他把学生按在书桌前，拿出一张卷子。"},{"t":"n","text":"「先做这个。」他说。"},{"t":"n","text":"学生说：「老师，这题我做过了。」"},{"t":"c","id":"luchen","text":"做过了就再做一遍。"},{"t":"n","text":"你站在门口，看见他弯腰给学生讲题。"},{"t":"n","text":"他的背影和当年图书馆三楼那个少年，慢慢重合。"},{"t":"n","text":"他抬起头，看见你。"},{"t":"c","id":"luchen","text":"别站着。过来看看，这题你也不会。"},{"t":"n","text":"你走过去。"},{"t":"n","text":"卷子上是一道很简单的应用题。你当然会。"},{"t":"n","text":"你还是坐下了。"},{"t":"n","text":"那天下午，你们三个人挤在一张书桌前。窗外的光照进来，落在纸上。"},{"t":"n","text":"他讲得很慢，一个字一个字。学生听懂了，他就在旁边画一个勾。"},{"t":"n","text":"画勾的时候，他的手很稳。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"认真把那道题做完","hint":"坐下来 · 陪他一会儿","eff":{"happy":4.0,"aff":2.0},"reply":[{"t":"n","text":"你做完了。他拿过去看，说：「步骤太啰嗦。」然后在你旁边写了一个更短的。"}]},{"label":"B","text":"说「这题我早会了」","hint":"拆他的台 · 老朋友","eff":{"happy":3.0,"eq":1.0},"reply":[{"t":"n","text":"他抬头看你一眼，说：「会也得做。学生看着。」"}]}]}],"quality":{"high":["你们后来还是每月见一次。","有一年他生病，住了半个月院。你去看了三次。","第三次，他把床摇起来，让你把电脑拿过来。","陆沉：「这个模型，你帮我看一眼。」","你说：「你先养病。」","他把电脑打开。","陆沉：「养病也是躺着。躺着可以看。」","你们在病房里改了一下午的方案。护士进来量体温，看了一眼屏幕，说：「你们这是上班呢。」","他抬头，很认真地说：「不是。这是玩。」"],"mid":["后来你们都忙。见面的次数从一个月一次，变成两个月，再变成一年两三次。","见面还是吃饭，还是挑毛病。","只是题越来越简单，饭吃得越来越慢。","有一次吃完饭，他说：「下次，带家属一起来。」","你说好。","那顿饭之后，你们隔了八个月才再见。","再见面的时候，两个人都已经会互相打招呼了。"],"low":["有一年，他调去了另一个城市。","走之前，他请你吃了一顿饭。饭桌上，他把那本深蓝的旧笔记推过来。","陆沉：「这个，你保管。」","你说：「这不是你的？」","他把手放在书上，按了一下。","陆沉：「现在是你家的了。」","他走了以后，你把书带回家，放在书架最上面。","有一年你把它拿下来，翻开。扉页上三个名字，都被涂掉了。","你想了想，又把书放回去了。","那本书在书架上放了很多年。你没有再翻开过。","有一年搬家，你把它装进箱子最底层。","箱子上写着「书」。","搬家那天下了雨。纸箱受潮，底部软了一块。","你把书一本一本拿出来，摊在阳台上晾。那本深蓝的，你放在了最上面。"]},"id":"luchen_23","ending":"friend","endingName":"结局三 · 一辈子的对手"}]}],"events":[{"id":"lc1","title":"他的生日","triggerWeek":30,"bg":"cafe","cast":["luchen"],"intro":[{"t":"n","text":"他的生日在十二月。你是在学生证上看到的。"},{"t":"n","text":"学生证压在图书馆的桌上，翻开的那一页正好是他的信息。他回来的时候，你正在看。"},{"t":"n","text":"他把学生证合上。"},{"t":"c","id":"luchen","text":"看什么。"},{"t":"n","text":"你说：「今天是你生日。」"},{"t":"n","text":"他没有承认，也没有否认。他把学生证塞进书包最里层。"}],"opts":[{"label":"A","text":"提前准备了东西","hint":"把东西递过去 · 别多说","eff":{"aff":4.0,"fin":-2.0,"happy":2.0},"reply":[{"t":"n","text":"你把东西递过去。是一支笔，和他用了三年的那支同款。"},{"t":"n","text":"他接过去，看了很久。"},{"t":"c","id":"luchen","text":"停产了。你哪儿买的。"},{"t":"n","text":"你说：「网上。最后一支。」"},{"t":"n","text":"他把笔帽拔下来，又扣上。扣了两次。"},{"t":"c","id":"luchen","text":"谢谢。"}]},{"label":"B","text":"当天说一句「生日快乐」","hint":"就说一句 · 不添东西","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"你说：「生日快乐。」"},{"t":"n","text":"他「嗯」了一声。"},{"t":"n","text":"那天晚上他做题做得比平时慢。闭馆的时候，他忽然说：「今天几号。」"},{"t":"n","text":"你说：「十七号。」"},{"t":"c","id":"luchen","text":"哦。"},{"t":"n","text":"他把书包背上。"},{"t":"c","id":"luchen","text":"我记错了。我以为是明天。"}]},{"label":"C","text":"忘了","hint":"日子太满 · 就过去了","eff":{"aff":-3.0,"happy":-2.0},"reply":[{"t":"n","text":"那天你忙到很晚，想起来的时候已经是第二天。"},{"t":"n","text":"你发了一条消息：「昨天是你生日？」"},{"t":"n","text":"他回：「嗯。」"},{"t":"n","text":"你问：「怎么不早说。」"},{"t":"n","text":"他回：「说了就不是生日了。」"}]}]},{"id":"lc2","title":"凌晨的打印店","triggerWeek":28,"bg":"cafe","cast":["luchen"],"intro":[{"t":"n","text":"凌晨一点，学校后门的打印店还亮着灯。"},{"t":"n","text":"他站在机器旁边，等一沓资料印出来。"},{"t":"n","text":"机器每印一张，就响一下。屋子里有一股热纸的味道。"},{"t":"n","text":"你推门进去。他回头。"},{"t":"c","id":"luchen","text":"你怎么也没睡。"},{"t":"n","text":"你说：「你也没睡。」"}],"opts":[{"label":"A","text":"陪他印完，一起吃碗面","hint":"把这一夜过完 · 别一个人","eff":{"aff":3.0,"stress":1.0,"happy":2.0,"fin":-1.0},"reply":[{"t":"n","text":"印完是两点。街对面的面摊还没收。"},{"t":"n","text":"你们一人一碗。他吃得很慢，吃完把汤也喝了。"},{"t":"c","id":"luchen","text":"这家比学校里的好。"},{"t":"n","text":"你说：「因为它贵三块。」"},{"t":"n","text":"他笑了一下。"}]},{"label":"B","text":"劝他回去睡","hint":"说一句实话 · 他未必听","eff":{"aff":1.0,"happy":1.0},"reply":[{"t":"n","text":"你说：「明天再印吧。你这样撑不住。」"},{"t":"n","text":"他把资料抱紧了一点。"},{"t":"c","id":"luchen","text":"明天印，就来不及了。"},{"t":"n","text":"你没有再劝。"},{"t":"n","text":"他印完，把机器关掉。"},{"t":"c","id":"luchen","text":"你先回去。我锁门。"}]},{"label":"C","text":"自己先走","hint":"各忙各的 · 也正常","eff":{},"reply":[{"t":"n","text":"你说你还有事，先走了。"},{"t":"n","text":"他点头。"},{"t":"n","text":"第二天上课，他的桌上放着一杯咖啡。已经凉了。"},{"t":"n","text":"你不知道是谁放的。你也没有问。"}]}]},{"id":"lc3","title":"他的家庭电话","triggerWeek":35,"bg":"cafe","cast":["luchen"],"intro":[{"t":"n","text":"他的手机在桌上震动。屏幕朝上，备注是「爸」。"},{"t":"n","text":"响了很久。他没有接。"},{"t":"n","text":"第二遍响起来的时候，你抬起头。他也在看你。"},{"t":"n","text":"他的手放在手机旁边，没有动。"}],"opts":[{"label":"A","text":"让他接","hint":"把手机推过去 · 不替他决定","eff":{"aff":2.0,"stress":2.0},"reply":[{"t":"n","text":"你把手机往他那边推了推。"},{"t":"n","text":"他看了两秒，拿起来，走到走廊上。"},{"t":"n","text":"他回来的时候，脸色没什么变化。"},{"t":"c","id":"luchen","text":"问我期末排名。"},{"t":"n","text":"你说：「你怎么说的。」"},{"t":"c","id":"luchen","text":"说了。"},{"t":"n","text":"他把手机扣在桌上。"},{"t":"c","id":"luchen","text":"他沉默了一会儿，说『还行』。"}]},{"label":"B","text":"帮他按掉","hint":"替他挡一下 · 他心里会记","eff":{"aff":-2.0,"happy":1.0},"reply":[{"t":"n","text":"你伸手，按了拒接。"},{"t":"n","text":"屏幕黑下去。他愣住。"},{"t":"n","text":"「你干嘛。」他说。"},{"t":"n","text":"你说：「你不想接。」"},{"t":"n","text":"他沉默了很久。"},{"t":"c","id":"luchen","text":"我是不想接。但那是我爸。"},{"t":"n","text":"那天晚上，他自己回拨了。站在走廊上，说了二十分钟。"}]},{"label":"C","text":"陪他听完","hint":"不接也不挂 · 就坐着","eff":{"aff":4.0,"stress":2.0,"eq":2.0},"reply":[{"t":"n","text":"电话响到自动挂断。"},{"t":"n","text":"你们谁也没说话。图书馆里只有翻页的声音。"},{"t":"n","text":"五分钟后，它又响了。他还是没接。"},{"t":"n","text":"第三遍响的时候，你伸手，把手机翻过来，屏幕朝下。"},{"t":"n","text":"他看着那个动作。"},{"t":"c","id":"luchen","text":"你不问我为什么不接。"},{"t":"n","text":"你说：「你想说的时候会说。」"},{"t":"n","text":"他低下头，过了很久。"},{"t":"c","id":"luchen","text":"他每次打电话，第一句都是『最近在做什么』。"},{"t":"n","text":"「然后呢。」"},{"t":"c","id":"luchen","text":"第二句就是『有没有退步』。"}]}]},{"id":"lc4","title":"出国申请","triggerWeek":43,"bg":"cafe","cast":["luchen"],"intro":[{"t":"n","text":"他的电脑开着，屏幕上是一份申请材料。英文的，写了一半。"},{"t":"n","text":"你把咖啡放在他手边。他抬起头。"},{"t":"c","id":"luchen","text":"你帮我看看。第二段。"},{"t":"n","text":"你看了。第二段写他为什么选这个方向，写了五行，全是术语。"},{"t":"n","text":"你说：「这段没有你。」"},{"t":"n","text":"他把电脑转回去，看了很久。"}],"opts":[{"label":"A","text":"帮他改","hint":"把「我」写进去 · 笨办法","eff":{"aff":4.0,"int":1.0,"happy":2.0},"reply":[{"t":"n","text":"你在他旁边坐下，让他说，你写。"},{"t":"n","text":"他说得很慢。说到一半，停下来。"},{"t":"c","id":"luchen","text":"这个不专业。"},{"t":"n","text":"你说：「先不专业。」"},{"t":"n","text":"写完，他看着屏幕，看了很久。"},{"t":"c","id":"luchen","text":"这不像申请材料。"},{"t":"n","text":"你说：「像你。」"}]},{"label":"B","text":"让他自己决定","hint":"不插手 · 也不替他选","eff":{"aff":1.0,"eq":1.0},"reply":[{"t":"n","text":"你说：「这个你自己写。你写得出来。」"},{"t":"n","text":"他看了你一眼，没说话。"},{"t":"n","text":"他写了三天。第四天，他把材料发出去。"},{"t":"n","text":"发完，他给你看第一段。"},{"t":"n","text":"第一段只有一句话：「我做这个方向，是因为一个人问过我一个问题。」"}]},{"label":"C","text":"问他会不会回来","hint":"问一句 · 会听见不确定","eff":{"aff":2.0,"happy":-1.0},"reply":[{"t":"n","text":"你问：「你会回来吗。」"},{"t":"n","text":"他合上电脑。"},{"t":"c","id":"luchen","text":"不知道。"},{"t":"n","text":"「不知道，还是不想说。」"},{"t":"n","text":"他看着桌面。"},{"t":"c","id":"luchen","text":"我不知道三年以后，我是什么样。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"luchen","text":"但我知道，我会记得今天。"}]}]},{"id":"lc5","title":"同学聚会","triggerWeek":50,"bg":"cafe","cast":["luchen"],"intro":[{"t":"n","text":"同学聚会在一家老饭店。包间的墙纸发黄，转盘上有一道裂。"},{"t":"n","text":"有人问他现在在做什么。他说了，说得很简短。"},{"t":"n","text":"有人问：「年薪多少。」"},{"t":"n","text":"他夹了一筷子菜，没有答。"},{"t":"n","text":"桌上安静了两秒，有人把话题岔开。"},{"t":"n","text":"散场以后，你们一起走到路口。"}],"opts":[{"label":"A","text":"一起去","hint":"坐在他旁边 · 挡住一些话","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"你坐他旁边。有人问起他父亲，你说：「叔叔退休了，身体挺好。」"},{"t":"n","text":"他看了你一眼。"},{"t":"n","text":"散场时，他说：「你刚才那句话，谢了。」"},{"t":"n","text":"你说：「哪句。」"},{"t":"n","text":"他没有答。"}]},{"label":"B","text":"各自去，各自走","hint":"保持距离 · 也省事","eff":{},"reply":[{"t":"n","text":"你到得晚，坐得远。他坐在另一头。"},{"t":"n","text":"中间隔着八个人和一盘没动的鱼。"},{"t":"n","text":"散场的时候，你们在门口碰上。"},{"t":"c","id":"luchen","text":"你先走。"},{"t":"n","text":"你说好。"}]},{"label":"C","text":"不去","hint":"不想应付 · 就不去","eff":{"aff":-1.0,"happy":2.0},"reply":[{"t":"n","text":"你没有去。"},{"t":"n","text":"那天晚上他发来一张照片。是包间里的一张桌子，杯子里是茶。"},{"t":"n","text":"配了一句：「他们问你怎么没来。」"},{"t":"n","text":"你问：「你怎么说的。」"},{"t":"n","text":"他回：「我说你有事。」"},{"t":"n","text":"过了两分钟，又来一条。"},{"t":"n","text":"「其实我想说，你不喜欢这种场合。」"}]}]},{"id":"lc6","title":"表慢三分钟","triggerWeek":28,"bg":"cafe","cast":["luchen"],"intro":[{"t":"n","text":"你发现他的表慢三分钟，是在一次交卷的时候。"},{"t":"n","text":"他看了一眼表，说「还有十分钟」，广播里已经报了「还剩七分钟」。"},{"t":"n","text":"你告诉他的时候，他只是「嗯」了一声。"},{"t":"n","text":"之后还有第二次，第三次。"},{"t":"n","text":"每一次他都「嗯」。"}],"opts":[{"label":"A","text":"提醒他去修","hint":"说一句 · 也许他不想修","eff":{"aff":1.0,"eq":1.0},"reply":[{"t":"n","text":"你说：「你去修一下吧。考试会误事。」"},{"t":"n","text":"他把表往上推了推。"},{"t":"c","id":"luchen","text":"不会误。"},{"t":"n","text":"「为什么。」"},{"t":"n","text":"他看了你一眼。"},{"t":"c","id":"luchen","text":"我从来不用最后三分钟。"}]},{"label":"B","text":"不问，自己心里记着","hint":"知道就行 · 不用说","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"你没有再说。"},{"t":"n","text":"以后每次约时间，你都会提前三分钟到。"},{"t":"n","text":"他每次都会说：「你来早了。」"},{"t":"n","text":"你说：「我习惯。」"},{"t":"n","text":"有一次他迟到了，跑过来，气还没喘匀。"},{"t":"c","id":"luchen","text":"我表……"},{"t":"n","text":"你说：「慢三分钟。我知道。」"},{"t":"n","text":"他站在那里，看了你很久。"}]},{"label":"C","text":"把自己的表也调慢三分钟","hint":"陪他慢一点 · 有点傻","eff":{"aff":5.0,"happy":3.0,"stress":-1.0},"reply":[{"t":"n","text":"你把表调慢了三分钟。"},{"t":"n","text":"第二天约在七点。你七点零三到。他已经在了。"},{"t":"n","text":"看见你，他抬了一下眉。"},{"t":"c","id":"luchen","text":"你迟到了。"},{"t":"n","text":"你说：「没有。我的表慢三分钟。」"},{"t":"n","text":"他愣住了。"},{"t":"n","text":"然后他把自己的手腕抬起来，跟你的表并在一起。"},{"t":"n","text":"两块表的指针，差了三分钟。"},{"t":"c","id":"luchen","text":"为什么。"},{"t":"n","text":"你说：「这样我就不会比你早。」"},{"t":"n","text":"他看着那两块表，很久没有说话。"}]}]}],"endingNames":{"stay":"结局一 · 两个不肯认输的人","miss":"结局二 · 我们都没输，只是没在一起","friend":"结局三 · 一辈子的对手"}};
